27	constexpr uint32_t OUTPUT_IDX_DQ = 0;
28	constexpr uint32_t OUTPUT_IDX_DK = 1;
29	constexpr uint32_t OUTPUT_IDX_DV = 2;
30	constexpr uint32_t OUTPUT_IDX_DPSE = 3;
31	constexpr uint32_t OUTPUT_IDX_DQ_ROPE = 4;
32	constexpr uint32_t OUTPUT_IDX_DK_ROPE = 5;
33	
34	constexpr uint32_t QUERY_INPUT_INDEX = 0;
35	constexpr uint32_t KEY_INPUT_INDEX = 1;
36	constexpr uint32_t VALUE_INPUT_INDEX = 2;
37	constexpr uint32_t DY_INPUT_INDEX = 3;
38	constexpr uint32_t SOFTMAX_MAX = 8;
39	constexpr uint32_t SOFTMAX_SUM = 9;
40	constexpr uint32_t ATTENTION_IN = 11;
41	constexpr uint32_t QUERY_ROPE_INPUT_INDEX = 22;
42	constexpr uint32_t KEY_ROPE_INPUT_INDEX = 23;
43	
44	constexpr uint32_t HEAD_NUM_IDX = 4;
45	constexpr uint32_t LAYOUT_ATTR_IDX = 5;
46	
47	constexpr uint32_t FAG_EMPTY_TILING_KEY = 0;
48	constexpr uint32_t TILING_KEY_1 = 1U;
49	constexpr size_t WORKSPACE_SIZE = static_cast<size_t>(100) * 1024 * 1024;
