51	static uint32_t CalculateTschBlockDim(const uint32_t sliceNum, const uint32_t aicCoreNum, const uint32_t aivCoreNum)
52	{
53	    uint32_t ration;
54	    if (aicCoreNum == 0U || aivCoreNum == 0U || aicCoreNum > aivCoreNum) {
55	        return sliceNum;
56	    }
57	    ration = aivCoreNum / aicCoreNum;
58	    return (sliceNum + (ration - 1)) / ration;
59	}
