61	// tiling func + tiling prepare
62	class FlashAttentionScoreGradEnhanceTiling {
63	  public:
64	    ge::graphStatus RunEmptyTiling(gert::TilingContext *context)
65	    {
66	        FlashAttentionScoreGradEnhanceTilingData *tilingData =
67	            context->GetTilingData<FlashAttentionScoreGradEnhanceTilingData>();
68	        uint64_t aicNum = 40; // 40: B3 default aicNum
69	        uint64_t aivNum = 20; // 20: B3 default aivNum
70	        auto platformInfoPtr = context->GetPlatformInfo();
71	        if (platformInfoPtr == nullptr) {
72	            auto compilePtr =
73	                reinterpret_cast<const FlashAttentionScoreGradEnhanceCompileInfo *>(context->GetCompileInfo());
74	            OP_CHECK_IF(compilePtr == nullptr, OP_LOGE(context, "compile_info is null"), return ge::GRAPH_FAILED);
75	            aivNum = compilePtr->aivNum;
76	            aicNum = compilePtr->aicNum;
77	        } else {
78	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
79	            aicNum = ascendcPlatform.GetCoreNumAic();
80	            aivNum = ascendcPlatform.GetCoreNumAiv();
81	        }
82	        OP_CHECK_IF(
83	            aivNum == 0, OP_LOGE("flash_attention_score_grad_enhance", "num of aiv is 0."), return GRAPH_FAILED);
84	        uint64_t dqNum =
85	            static_cast<uint64_t>(context->GetOutputShape(OUTPUT_IDX_DQ)->GetStorageShape().GetShapeSize());
86	        if (dqNum % aivNum == 0ULL) {
87	            tilingData->emptyTensorTilingData.SetFormerDqNum(aivNum);
88	            tilingData->emptyTensorTilingData.SetSingleCoreDqNum(dqNum / aivNum);
89	            tilingData->emptyTensorTilingData.SetTailCoreDqNum(0);
90	        } else {
91	            tilingData->emptyTensorTilingData.SetFormerDqNum(dqNum % aivNum);
92	            tilingData->emptyTensorTilingData.SetSingleCoreDqNum(dqNum / aivNum + 1);
93	            tilingData->emptyTensorTilingData.SetTailCoreDqNum(dqNum / aivNum);
94	        }
95	        uint64_t dkNum =
96	            static_cast<uint64_t>(context->GetOutputShape(OUTPUT_IDX_DK)->GetStorageShape().GetShapeSize());
97	        if (dkNum % aivNum == 0ULL) {
98	            tilingData->emptyTensorTilingData.SetFormerDkNum(aivNum);
99	            tilingData->emptyTensorTilingData.SetSingleCoreDkNum(dkNum / aivNum);
100	            tilingData->emptyTensorTilingData.SetTailCoreDkNum(0);
101	        } else {
102	            tilingData->emptyTensorTilingData.SetFormerDkNum(dkNum % aivNum);
103	            tilingData->emptyTensorTilingData.SetSingleCoreDkNum(dkNum / aivNum + 1);
104	            tilingData->emptyTensorTilingData.SetTailCoreDkNum(dkNum / aivNum);
105	        }
106	        uint64_t dvNum =
107	            static_cast<uint64_t>(context->GetOutputShape(OUTPUT_IDX_DV)->GetStorageShape().GetShapeSize());
108	        if (dvNum % aivNum == 0ULL) {
109	            tilingData->emptyTensorTilingData.SetFormerDvNum(aivNum);
110	            tilingData->emptyTensorTilingData.SetSingleCoreDvNum(dvNum / aivNum);
111	            tilingData->emptyTensorTilingData.SetTailCoreDvNum(0);
112	        } else {
113	            tilingData->emptyTensorTilingData.SetFormerDvNum(dvNum % aivNum);
114	            tilingData->emptyTensorTilingData.SetSingleCoreDvNum(dvNum / aivNum + 1);
115	            tilingData->emptyTensorTilingData.SetTailCoreDvNum(dvNum / aivNum);
116	        }
117	        const gert::StorageShape *dpseShape = context->GetOutputShape(OUTPUT_IDX_DPSE);
118	        uint64_t dpseNum =
119	            (dpseShape == nullptr) ? 0 : static_cast<uint64_t>(dpseShape->GetStorageShape().GetShapeSize());
120	        if (dpseNum % aivNum == 0ULL) {
121	            tilingData->emptyTensorTilingData.SetFormerDpseNum(aivNum);
122	            tilingData->emptyTensorTilingData.SetSingleCoreDpseNum(dpseNum / aivNum);
123	            tilingData->emptyTensorTilingData.SetTailCoreDpseNum(0);
124	        } else {
125	            tilingData->emptyTensorTilingData.SetFormerDpseNum(dpseNum % aivNum);
126	            tilingData->emptyTensorTilingData.SetSingleCoreDpseNum(dpseNum / aivNum + 1);
127	            tilingData->emptyTensorTilingData.SetTailCoreDpseNum(dpseNum / aivNum);
128	        }
129	
130	        context->SetTilingKey(FAG_EMPTY_TILING_KEY);
131	        auto sliceNum =
132	            (dqNum < aivNum && dkNum < aivNum && dpseNum < aivNum) ? std::max(std::max(dqNum, dkNum), dpseNum) : aivNum;
133	        context->SetBlockDim(CalculateTschBlockDim(sliceNum, aicNum, aivNum));
134	        size_t *workspaces = context->GetWorkspaceSizes(1);
135	        workspaces[0] = WORKSPACE_SIZE;
136	        return ge::GRAPH_SUCCESS;
137	    }
138	};
