140	static bool IsEmptyOutput(gert::TilingContext *context)
141	{
142	    const gert::StorageShape *dqShape = context->GetOutputShape(OUTPUT_IDX_DQ);
143	    const gert::StorageShape *dqRopeShape = context->GetOutputShape(OUTPUT_IDX_DQ_ROPE);
144	    const gert::StorageShape *dkShape = context->GetOutputShape(OUTPUT_IDX_DK);
145	    const gert::StorageShape *dkRopeShape = context->GetOutputShape(OUTPUT_IDX_DK_ROPE);
146	    const gert::StorageShape *dvShape = context->GetOutputShape(OUTPUT_IDX_DV);
147	    if (dqShape != nullptr && dkShape != nullptr && dvShape != nullptr) {
148	        if (dqShape->GetStorageShape().GetShapeSize() == 0 || dkShape->GetStorageShape().GetShapeSize() == 0 ||
149	            dvShape->GetStorageShape().GetShapeSize() == 0) {
150	            return true;
151	        }
152	    }
153	    if (dqRopeShape != nullptr && dkRopeShape != nullptr) {
154	        if (dqRopeShape->GetStorageShape().GetShapeSize() == 0 || dkRopeShape->GetStorageShape().GetShapeSize() == 0) {
155	            return true;
156	        }
157	    }
158	    return false;
159	}
