161	static ge::graphStatus CheckAttrs(gert::TilingContext *context)
162	{
163	    auto attrs = context->GetAttrs();
164	    OP_CHECK_NULL_WITH_CONTEXT(context, attrs);
165	    size_t idx = 0;
166	    auto scaleValuePtr = attrs->GetAttrPointer<float>(idx++);
167	    auto keepProbPtr = attrs->GetAttrPointer<float>(idx++);
168	    auto preTokensPtr = attrs->GetAttrPointer<int64_t>(idx++);
169	    auto nextTokensPtr = attrs->GetAttrPointer<int64_t>(idx++);
170	    auto n1SizePtr = attrs->GetAttrPointer<uint32_t>(idx++);
171	    auto inputLayoutPtr = attrs->GetAttrPointer<char>(idx++);
172	    size_t *workspaces = context->GetWorkspaceSizes(1);
173	
174	    OP_CHECK_NULL_WITH_CONTEXT(context, scaleValuePtr);
175	    OP_CHECK_NULL_WITH_CONTEXT(context, keepProbPtr);
176	    OP_CHECK_NULL_WITH_CONTEXT(context, preTokensPtr);
177	    OP_CHECK_NULL_WITH_CONTEXT(context, nextTokensPtr);
178	    OP_CHECK_NULL_WITH_CONTEXT(context, n1SizePtr);
179	    OP_CHECK_NULL_WITH_CONTEXT(context, inputLayoutPtr);
180	    OP_CHECK_NULL_WITH_CONTEXT(context, workspaces);
181	    return ge::GRAPH_SUCCESS;
182	}
