184	static ge::graphStatus CheckBaseInput(gert::TilingContext *context)
185	{
186	    auto &queryShape = context->GetInputShape(QUERY_INPUT_INDEX)->GetStorageShape();
187	    auto &keyShape = context->GetInputShape(KEY_INPUT_INDEX)->GetStorageShape();
188	    auto &valueShape = context->GetInputShape(VALUE_INPUT_INDEX)->GetStorageShape();
189	    int64_t headNum = *context->GetAttrs()->GetAttrPointer<int>(HEAD_NUM_IDX);
190	    OP_CHECK_IF(headNum == 0, OP_LOGE(context, "headNum is 0."), return ge::GRAPH_FAILED);
191	    const char *inputLayout = context->GetAttrs()->GetAttrPointer<char>(LAYOUT_ATTR_IDX);
192	    if (strlen(inputLayout) == 3) { // 3: BSH or SBH or TND
193	        if (inputLayout[0] == 'B') {
194	            // layout is BSH
195	            OP_CHECK_IF((queryShape.GetDim(0) != keyShape.GetDim(0)),
196	                        OP_LOGE(context, "query or key shape is invalid"),
197	                        return ge::GRAPH_FAILED);
198	            OP_CHECK_IF(
199	                queryShape.GetDim(2) % headNum != 0,
200	                OP_LOGE(context, "h1 [%ld] should be a multiple of headNum [%ld].", queryShape.GetDim(2), headNum),
201	                return ge::GRAPH_FAILED);
202	        } else if (inputLayout[0] == 'T') { // TND  N1 != N2
203	            OP_CHECK_IF(headNum != queryShape.GetDim(1),
204	                        OP_LOGE(context, "headNum is [%ld], but got n1 [%ld].", headNum, queryShape.GetDim(1)),
205	                        return ge::GRAPH_FAILED);
206	            return ge::SUCCESS;
207	        } else {
208	            // layout is SBH
209	            OP_CHECK_IF((queryShape.GetDim(1) != keyShape.GetDim(1)),
210	                        OP_LOGE(context, "query or key shape is invalid"),
211	                        return ge::GRAPH_FAILED);
212	            OP_CHECK_IF(
213	                queryShape.GetDim(2) % headNum != 0,
214	                OP_LOGE(context, "h1 [%ld] should be a multiple of headNum [%ld].", queryShape.GetDim(2), headNum),
215	                return ge::GRAPH_FAILED);
216	        }
217	        // kD < vD
218	        OP_CHECK_IF((keyShape.GetDim(2) < valueShape.GetDim(2)),
219	                    OP_LOGE(context, "key or value shape is invalid"),
220	                    return ge::GRAPH_FAILED);
221	    } else if (strlen(inputLayout) == 4) { // 4: layout is BNSD or BSND
222	        OP_CHECK_IF((queryShape.GetDim(0) != keyShape.GetDim(0)),
223	                    OP_LOGE(context, "query or key shape is invalid"),
224	                    return ge::GRAPH_FAILED);
225	        OP_CHECK_IF((queryShape.GetDim(3) != keyShape.GetDim(3)),
226	                    OP_LOGE(context, "query or key shape is invalid"),
227	                    return ge::GRAPH_FAILED);
228	        if (inputLayout[1] == 'N') {
229	            OP_CHECK_IF(headNum != queryShape.GetDim(1),
230	                        OP_LOGE(context, "headNum is [%ld], but got n1 [%ld].", headNum, queryShape.GetDim(1)),
231	                        return ge::GRAPH_FAILED);
232	        } else {
233	            OP_CHECK_IF(headNum != queryShape.GetDim(2),
234	                        OP_LOGE(context, "headNum is [%ld], but got n1 [%ld].", headNum, queryShape.GetDim(2)),
235	                        return ge::GRAPH_FAILED);
236	        }
237	        OP_CHECK_IF((keyShape.GetDim(3) < valueShape.GetDim(3)),
238	                    OP_LOGE(context, "key or value shape is invalid"),
239	                    return ge::GRAPH_FAILED);
240	    } else {
241	        OP_LOGE(context, "invalid input_layout[%s].", inputLayout);
242	        return ge::GRAPH_FAILED;
243	    }
244	    return ge::SUCCESS;
245	}
246	
247	static ge::graphStatus CheckParams(gert::TilingContext *context)
248	{
249	    OP_CHECK_IF(context == nullptr, OP_LOGE("CheckParams", "context is null."), return ge::GRAPH_FAILED);
250	    OP_CHECK_IF(CheckAttrs(context) != ge::GRAPH_SUCCESS,
251	                OP_LOGE(context->GetNodeName(), "invalid attrs"),
252	                return ge::GRAPH_FAILED);
253	    if ((context->GetInputShape(QUERY_ROPE_INPUT_INDEX) != nullptr &&
254	         context->GetInputShape(KEY_ROPE_INPUT_INDEX) == nullptr) ||
255	        (context->GetInputShape(QUERY_ROPE_INPUT_INDEX) == nullptr &&
256	         context->GetInputShape(KEY_ROPE_INPUT_INDEX) != nullptr)) {
257	        OP_LOGE(context, "input shape Query Rope and Key Rope must be either both defined or both undefined.");
258	        return ge::GRAPH_FAILED;
259	    }
260	
261	    if (context->GetInputShape(QUERY_INPUT_INDEX) != nullptr && context->GetInputShape(KEY_INPUT_INDEX) != nullptr &&
262	        context->GetInputShape(VALUE_INPUT_INDEX) != nullptr && context->GetInputShape(DY_INPUT_INDEX) != nullptr &&
263	        context->GetOptionalInputShape(SOFTMAX_MAX) != nullptr &&
264	        context->GetOptionalInputShape(SOFTMAX_SUM) != nullptr &&
265	        context->GetOptionalInputShape(ATTENTION_IN) != nullptr) {
266	        if (CheckBaseInput(context) == ge::GRAPH_SUCCESS) {
267	            return ge::SUCCESS;
268	        }
269	    }
270	    OP_LOGE(context, "fail to get shape or attr from context");
271	    return ge::GRAPH_FAILED;
272	}
273	
274	ASCENDC_EXTERN_C ge::graphStatus TilingFlashAttentionGradScore(gert::TilingContext *context)
275	{
276	    if (CheckParams(context) != ge::GRAPH_SUCCESS) {
277	        return ge::GRAPH_FAILED;
278	    }
279	    auto compilePtr = reinterpret_cast<const FlashAttentionScoreGradEnhanceCompileInfo *>(context->GetCompileInfo());
280	    OP_CHECK_IF(compilePtr == nullptr, OP_LOGE(context, "compile_info is null"), return ge::GRAPH_FAILED);
281	    auto socVersion = compilePtr->socVersion;
282	    if (socVersion == platform_ascendc::SocVersion::ASCEND910B ||
283	        socVersion == platform_ascendc::SocVersion::ASCEND910_93) {
284	        OP_LOGW(context, "Current soc version is ASCEND910B or ASCEND910_93.");
285	        if (IsEmptyOutput(context)) {
286	            FlashAttentionScoreGradEnhanceTiling flashAttentionScoreGradEnhanceTiling;
287	            return flashAttentionScoreGradEnhanceTiling.RunEmptyTiling(context);
288	        }
289	    } else {
290	        OP_LOGE(context, "Only support soc version ASCEND910B and ASCEND910_93.");
291	        return ge::GRAPH_FAILED;
292	    }
293	    return TilingRegistryNew::GetInstance().DoTilingImpl(context);
294	}
