static inline uint32_t Gcd(const uint32_t a, const uint32_t b) // a >= b
{
    if (b == 0U) {
        return a;
    }
    if (b > a) {
        return Gcd(b, a);
    }
    if (a % b == 0U) {
        return b;
    }
    return Gcd(b, a % b);
}

static inline int64_t CeilCommon(const int64_t num1, const int64_t num2)
{
    if (num2 == 0) {
        return 0;
    }
    return (num1 + num2 - 1) / num2;
}

static inline int64_t Align(const int64_t n)
{
    return (n + BYTE_PER_BLOCK - 1) & (~(BYTE_PER_BLOCK - 1));
}

static inline uint32_t AlignData(const uint32_t a, const uint32_t b)
{
    if (b == 0U) {
        return a;
    }
    return (a + b - 1U) / b * b;
}

template <class T>
static inline auto AlignTo(const T n, const T alignSize) -> T
{
    if (alignSize == 0) {
        return 0;
    }
    return (n + alignSize - 1) & (~(alignSize - 1));
}

template <typename T>
static inline auto AlignUp(T num1, T num2) -> T
{
    if (num2 == 0) {
        return 0;
    }
    if (num1 < 0) {
        return -(-num1 / num2) * num2;
    }
    return (num1 + num2 - 1) / num2 * num2;
}
