178	ge::graphStatus CheckAttentionInShape(gert::TilingContext *context)
179	{
180	    auto attentionInShape = context->GetOptionalInputShape(ATTENTION_IN);
181	    if (attentionInShape == nullptr) {
182	        return ge::GRAPH_SUCCESS;
183	    }
184	    auto queryShape = context->GetInputShape(QUERY);
185	    auto attentionInShapeDim = attentionInShape->GetStorageShape().GetDimNum();
186	    auto queryShapeDim = queryShape->GetStorageShape().GetDimNum();
187	    if (attentionInShapeDim != queryShapeDim) {
188	        OP_LOGE(
189	            context, "The dimnum of attentionIn %zu should be equal to query %zu", attentionInShapeDim, queryShapeDim);
190	        return ge::GRAPH_FAILED;
191	    }
192	    for (size_t i = 0; i < queryShapeDim; i++) {
193	        // No matter TND, SBH, BSH, BSND, BNSD, the last dim could be different
194	        if (i == queryShapeDim - 1) {
195	            continue;
196	        } else if (attentionInShape->GetStorageShape().GetDim(i) != queryShape->GetStorageShape().GetDim(i)) {
197	            OP_LOGE(context,
198	                    "The dim %zu of attentionIn shape is invalid, got %ld, should be %ld",
199	                    i,
200	                    attentionInShape->GetStorageShape().GetDim(i),
201	                    queryShape->GetStorageShape().GetDim(i));
202	            return ge::GRAPH_FAILED;
203	        }
204	    }
205	
206	    return ge::GRAPH_SUCCESS;
207	}
