316	bool IsSameShape(const gert::StorageShape *aShape, const gert::StorageShape *bShape)
317	{
318	    OP_CHECK_IF((aShape == nullptr) || (bShape == nullptr),
319	                OP_LOGW("flash_attention_score_grad_enhance_tiling_common", "aShape or bShape is nullptr."),
320	                return false);
321	    uint32_t dimSizeA = aShape->GetStorageShape().GetDimNum();
322	    uint32_t dimSizeB = bShape->GetStorageShape().GetDimNum();
323	    if (dimSizeA != dimSizeB) {
324	        return false;
325	    }
326	
327	    for (uint32_t i = 0; i < dimSizeA; i++) {
328	        auto dimA = aShape->GetStorageShape().GetDim(i);
329	        auto dimB = bShape->GetStorageShape().GetDim(i);
330	        if (dimA != dimB) {
331	            return false;
332	        }
333	    }
