337	bool IsSameShapeButValueDLeEqD(const gert::StorageShape *aShape, const gert::StorageShape *bShape)
338	{
339	    OP_CHECK_IF((aShape == nullptr) || (bShape == nullptr),
340	                OP_LOGW("flash_attention_score_grad_enhance_tiling_common", "aShape or bShape is nullptr."),
341	                return false);
342	    uint32_t dimSizeA = aShape->GetStorageShape().GetDimNum();
343	    uint32_t dimSizeB = bShape->GetStorageShape().GetDimNum();
344	    if (dimSizeA != dimSizeB) {
345	        return false;
346	    }
347	
348	    for (uint32_t i = 0; i < dimSizeA; i++) {
349	        if (i == dimSizeA - 1) {
350	            auto dimD = aShape->GetStorageShape().GetDim(i);
351	            auto dimValueD = bShape->GetStorageShape().GetDim(i);
352	            return dimValueD <= dimD;
353	        } else {
354	            auto dimA = aShape->GetStorageShape().GetDim(i);
355	            auto dimB = bShape->GetStorageShape().GetDim(i);
356	            if (dimA != dimB) {
357	                return false;
358	            }
359	        }
360	    }
361	    return true;
362	}
