364	bool isTndSABHit(const gert::TilingContext *context)
365	{
366	    auto actualSeqQLenTensor = context->GetOptionalInputTensor(ACTUAL_SEQ_Q_LEN);
367	    auto actualSeqKVLenTensor = context->GetOptionalInputTensor(ACTUAL_SEQ_KV_LEN);
368	    bool isTND = actualSeqQLenTensor != nullptr && actualSeqQLenTensor->GetShapeSize() > 0 &&
369	                 actualSeqKVLenTensor != nullptr && actualSeqKVLenTensor->GetShapeSize() > 0;
370	    if (isTND) {
371	        const int64_t *qTensor = actualSeqQLenTensor->GetData<int64_t>();
372	        const int64_t *kvTensor = actualSeqKVLenTensor->GetData<int64_t>();
373	        const size_t actualSeqQLen = static_cast<size_t>(actualSeqQLenTensor->GetShapeSize());
374	
375	        uint64_t qSum = 0;
376	        uint64_t kvSum = 0;
377	        uint64_t len = 1;
378	
379	        for (int64_t i = actualSeqQLen - 1; i >= 0; --i) {
380	            if (qTensor[i] != 0) {
381	                qSum = qTensor[i];
382	                kvSum = kvTensor[i];
383	                len = i + 1;
384	                break;
385	            }
386	        }
387	
388	        if ((qSum / len >= SAB_TND_SIZE) && (kvSum / len >= SAB_TND_SIZE)) {
389	            return true;
390	        }
391	    }
392	
393	    return false;
394	}
