    auto dim2 = softmaxSumShape->GetStorageShape().GetDim(2); // 2:8

    // softmaxSum pad to 8
    if (strcmp(tndSoftmaxIn, "same_as_input") == 0) {
        OP_CHECK_IF((dim0 != n1 || dim1 != t1 || dim2 != 8),
                    OP_LOGE(context,
                            "The shape of softmaxSum is invalid when softmax_in_layout is same_as_input, got "
                            "(%ld,%ld,%ld), should be (%ld,%ld,8) ",
                            dim0,
                            dim1,
                            dim2,
                            n1,
                            t1),
                    return ge::GRAPH_FAILED);
    } else {
        OP_CHECK_IF((dim0 != t1 || dim1 != n1 || dim2 != 8),
                    OP_LOGE(context,
