private:
    __aicore__ inline __attribute__((always_inline)) void Cube1Compute(const AddrInfo &shapeInfo, 
                                                                       __gm__ TYPE *left, 
                                                                       __gm__ TYPE *right, 
                                                                       __gm__ float *out);
