184	    sparseMode = tilingData->mlaTensorTilingData.sparseMode;
185	    AscendC::SetFlag<HardEvent::MTE3_MTE2>(static_cast<int32_t>(mte2WaitMte3));
186	    AscendC::WaitFlag<HardEvent::MTE3_MTE2>(static_cast<int32_t>(mte2WaitMte3));
187	    if (taskId == 0 && sparseMode != 0) {
188	        LocalTensor<uint8_t> attenMaskUbuint8 =
189	            unifiedBuffer.GetWithOffset<uint8_t>(16 * 1024 / sizeof(uint8_t), BoolBegin);
190	        CopyInAttenMaskBool(attenMaskUbuint8, 0, BASE_BLOCK_LENGTH, BASE_BLOCK_LENGTH);
191	    }
192	    AscendC::PipeBarrier<PIPE_V>();
193	    for (uint32_t i = 0; i < blockLen; ++i) {
194	        auto &blockInfo = addrs.VecBlkInfo[i];
195	        ///////////////////////////////////////////////////////////////
196	        // do scalar calculate
197	        ///////////////////////////////////////////////////////////////
198	        GetSeqQlenKvlenByBidx(blockInfo.batchIdx, actualS1Len, actualS2Len);
199	        s1CubeExtend = blockInfo.lengthy;
200	        s2CubeExtend = BASE_BLOCK_LENGTH;
201	        // split info
202	        s1VecSize = (s1CubeExtend + 1) / 2;
203	        s2VecSize = BASE_BLOCK_LENGTH;
204	        s1Extend = subIdx ? s1CubeExtend - s1VecSize : s1VecSize;
205	        s2Extend = blockInfo.lengthx;
206	        s2ExtendAlign = (s2Extend + 15) / 16 * 16;
207	        // offset
208	        sfmgOffset = 0;
209	        if (blockInfo.batchIdx > 0) {
210	            sfmgOffset = ((__gm__ int64_t *)actual_seq_qlen_addr)[blockInfo.batchIdx - 1] * n2 * g * 8;
211	        }
212	        sfmgOffset += ((blockInfo.n2Idx * g + blockInfo.gIdx) * actualS1Len + blockInfo.S1Idx * S1_CUBESIZE +
213	                       curS1Idx * s1VecSize) *
214	                      8;
215	
216	        if (tndSoftmaxIn) {
217	            int64_t innerRowOffsetLeft =
218	                unlikely(blockInfo.batchIdx == 0) ?
219	                    0 :
220	                    ((__gm__ int64_t *)actual_seq_qlen_addr)[blockInfo.batchIdx - 1] * 32 / sizeof(float);
221	            int64_t originInnerBatchOffset = ((blockInfo.n2Idx * g + blockInfo.gIdx) * actualS1Len +
222	                                              blockInfo.S1Idx * S1_CUBESIZE + curS1Idx * s1VecSize) *
223	                                             32 / sizeof(float);
224	            softMaxOffset = ((((__gm__ int64_t *)actual_seq_qlen_addr)[batch - 1] * 32 / sizeof(float)) *
225	                                 (blockInfo.n2Idx * g + blockInfo.gIdx) +
226	                             innerRowOffsetLeft + originInnerBatchOffset % (actualS1Len * 32 / sizeof(float)));
227	        } else {
228	            softMaxOffset = sfmgOffset;
229	        }
230	
231	        // copyIn cube_workspace params
232	        copyInOffset = cubeBlockIdx * cubeBaseMN * 2 + pingpongIdx * cubeBaseMN + blockInfo.offset +
233	                       curS1Idx * s1VecSize * s2CubeExtend;
234	        copyInParam = {static_cast<uint16_t>(s1Extend), static_cast<uint16_t>(s2ExtendAlign * sizeof(float)),
235	                       static_cast<uint16_t>((s2CubeExtend - s2ExtendAlign) * sizeof(float)), 0};
236	        // copyOut cube_workspace params
237	        copyOutOffset = 2 * ((cubeBlockIdx * cubeBaseMN * 2 + pingpongIdx * cubeBaseMN + blockInfo.offset) +
238	                             (curS1Idx * s1VecSize * s2CubeExtend));
239	        copyOutParam = {static_cast<uint16_t>(s1Extend), static_cast<uint16_t>(s2ExtendAlign * sizeof(IN_TYPE)), 0,
240	                        static_cast<uint16_t>((s2CubeExtend - s2ExtendAlign) * sizeof(IN_TYPE))};
241	        ///////////////////////////////////////////////////////////////
242	        // do vector calculate
243	        ///////////////////////////////////////////////////////////////
244	        event_t mte2WaitMte3A = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE3_MTE2>());
245	        event_t mte2WaitMte3B = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE3_MTE2>());
246	        SubGrapA(i, blockInfo, mte2WaitMte3A);
247	        SubGrapB(i, blockInfo, mte2WaitMte3B);
248	        GetTPipePtr()->ReleaseEventID<HardEvent::MTE3_MTE2>(mte2WaitMte3A);
249	        GetTPipePtr()->ReleaseEventID<HardEvent::MTE3_MTE2>(mte2WaitMte3B);
250	    }
251	}
252	
253	template <typename IN_TYPE, class TILING_TYPE>
254	__aicore__ inline void VecOp<IN_TYPE, TILING_TYPE>::GetSeqQlenKvlenByBidx(int64_t bIdx, int64_t &actualSeqQlen,
255	                                                                          int64_t &actualSeqKvlen)
256	{
257	    if (unlikely(bIdx == 0)) {
258	        actualSeqQlen = ((__gm__ int64_t *)actual_seq_qlen_addr)[0];
259	        actualSeqKvlen = ((__gm__ int64_t *)actual_seq_kvlen_addr)[0];
260	    } else {
261	        actualSeqQlen =
262	            ((__gm__ int64_t *)actual_seq_qlen_addr)[bIdx] - ((__gm__ int64_t *)actual_seq_qlen_addr)[bIdx - 1];
263	        actualSeqKvlen =
264	            ((__gm__ int64_t *)actual_seq_kvlen_addr)[bIdx] - ((__gm__ int64_t *)actual_seq_kvlen_addr)[bIdx - 1];
265	    }
266	    return;
267	}
268	
269	template <typename IN_TYPE, class TILING_TYPE>
270	__aicore__ inline void VecOp<IN_TYPE, TILING_TYPE>::CopyInAttenMaskBool(LocalTensor<uint8_t> &dstTensor,
271	                                                                        int64_t attenMaskOffset, uint32_t s1Extend,
272	                                                                        uint32_t s2Extend)
273	{
274	    AscendC::DataCopyExtParams intriParams;
275	    intriParams.blockCount = s1Extend;
276	    intriParams.blockLen = s2Extend * sizeof(uint8_t);
277	    intriParams.srcStride = (AttenMaskDimS2 - s2Extend) * sizeof(uint8_t);
278	    intriParams.dstStride = 0;
279	    intriParams.rsv = 0;
280	
281	    DataCopyPad(dstTensor, attenMaskU8Gm[attenMaskOffset], intriParams, {false, 0, 0, 0});
282	}
283	
284	template <typename IN_TYPE, class TILING_TYPE>
285	__aicore__ inline void VecOp<IN_TYPE, TILING_TYPE>::CalcAttenMaskBool(LocalTensor<float> &dstTensor,
286	                                                                      LocalTensor<uint8_t> srcTensor, uint32_t s1Extend,
287	                                                                      uint32_t s2SrcExtend, uint32_t s2MaskExtend,
288	                                                                      uint8_t maskType)
289	{
290	    LocalTensor<uint8_t> tmpUbBuffer =
291	        unifiedBuffer.GetWithOffset<uint8_t>(TMP_UB_SIZE / sizeof(uint8_t), TMP_UB_OFFSET);
292	    float scalar;
293	    if constexpr (IsSameType<float, float>::value) {
294	        uint32_t tmp = 0xFF7FFFFF;
295	        scalar = *((float *)&tmp);
296	    } else {
297	        uint16_t tmp = 0xFBFF;
298	        scalar = *((IN_TYPE *)&tmp);
299	    }
300	    SelectWithBytesMaskShapeInfo info;
301	    info.firstAxis = s1Extend;
302	    info.srcLastAxis = s2SrcExtend;
303	    info.maskLastAxis = s2MaskExtend;
304	    dstTensor.SetSize(info.firstAxis * info.srcLastAxis);
305	    srcTensor.SetSize(info.firstAxis * info.maskLastAxis);
306	    SelectWithBytesMask<float, uint8_t, false>(dstTensor, dstTensor, scalar, srcTensor, tmpUbBuffer, info);
307	}
308	
309	template <typename IN_TYPE, class TILING_TYPE>
310	__aicore__ inline void VecOp<IN_TYPE, TILING_TYPE>::CopyInSoftMax(LocalTensor<float> &dstTensor, uint32_t s1Extend,
311	                                                                  uint32_t softMaxOffset)
312	{
313	    DataCopyPad(dstTensor, softmaxSumGm[softMaxOffset], {1, static_cast<uint16_t>(s1Extend * BLOCK_SIZE), 0, 0},
314	                {false, 0, 0, 0});
315	    DataCopyPad(dstTensor[64 * 8], softmaxMaxGm[softMaxOffset], {1, static_cast<uint16_t>(s1Extend * BLOCK_SIZE), 0, 0},
316	                {false, 0, 0, 0});
317	}
318	
319	template <typename IN_TYPE, class TILING_TYPE>
320	__aicore__ inline void
321	VecOp<IN_TYPE, TILING_TYPE>::CalcSoftMax(LocalTensor<float> &dstTensor, LocalTensor<float> &src0Tensor,
322	                                         LocalTensor<float> &src1Tensor, uint32_t s1Extend, uint32_t s2Extend,
323	                                         uint32_t s2ExtendAlign, const SoftMaxTiling &tiling)
324	{
325	    bool isBasicBlock = (s1Extend % 8 == 0) && (s2Extend % 64 == 0);
326	    if (isBasicBlock) {
327	        LocalTensor<uint8_t> sharedTmp =
328	            unifiedBuffer.GetWithOffset<uint8_t>(TMP_UB_SIZE / sizeof(uint8_t), TMP_UB_OFFSET);
329	        uint32_t shapeArray1[2];
330	        shapeArray1[0] = s1Extend;
331	        shapeArray1[1] = s2Extend;
332	        dstTensor.SetShapeInfo(ShapeInfo(2, shapeArray1, AscendC::DataFormat::ND));
333	        src0Tensor.SetShapeInfo(ShapeInfo(2, shapeArray1, AscendC::DataFormat::ND));
334	        SimpleSoftMax<float, false, true>(dstTensor, src1Tensor, src1Tensor[64 * 8], src0Tensor, sharedTmp, tiling);
335	    } else {
336	        LocalTensor<float> vecOutBuffer =
337	            unifiedBuffer.GetWithOffset<float>(TMP_UB_SIZE / sizeof(float), TMP_UB_OFFSET);
338	        uint32_t sub_block_count = (s2Extend + cal_repeat_num - 1) / cal_repeat_num;
339	        for (uint32_t subIdx = 0; subIdx < sub_block_count; subIdx++) {
340	            uint32_t subMaskCount =
341	                (subIdx == sub_block_count - 1) ? (s2Extend - subIdx * cal_repeat_num) : cal_repeat_num;
342	            Sub(dstTensor[subIdx * cal_repeat_num], src0Tensor[subIdx * cal_repeat_num], src1Tensor[64 * 8],
343	                subMaskCount, s1Extend,
344	                {static_cast<uint8_t>(1), static_cast<uint8_t>(1), 0, static_cast<uint8_t>(s2ExtendAlign / 8),
345	                 static_cast<uint8_t>(s2ExtendAlign / 8), 1});
346	            AscendC::PipeBarrier<PIPE_V>();
347	            Exp(vecOutBuffer[subIdx * cal_repeat_num], dstTensor[subIdx * cal_repeat_num], subMaskCount, s1Extend,
348	                {static_cast<uint8_t>(1), static_cast<uint8_t>(1), static_cast<uint8_t>(s2ExtendAlign / 8),
349	                 static_cast<uint8_t>(s2ExtendAlign / 8)});
350	            AscendC::PipeBarrier<PIPE_V>();
351	            Div(dstTensor[subIdx * cal_repeat_num], vecOutBuffer[subIdx * cal_repeat_num], src1Tensor, subMaskCount,
352	                s1Extend,
353	                {static_cast<uint8_t>(1), static_cast<uint8_t>(1), 0, static_cast<uint8_t>(s2ExtendAlign / 8),
354	                 static_cast<uint8_t>(s2ExtendAlign / 8), 1});
355	            AscendC::PipeBarrier<PIPE_V>();
356	        }
357	    }
358	}
359	
360	template <typename IN_TYPE, class TILING_TYPE>
361	__aicore__ inline void VecOp<IN_TYPE, TILING_TYPE>::SubGrapA(int64_t curIdx, const VecBlockInfo &blockInfo,
362	                                                             event_t mte2WaitMte3A)
363	{
364	    uint32_t ubBufferOffset = 0;
365	    if (curIdx > 0) {
366	        AscendC::WaitFlag<HardEvent::MTE3_MTE2>(static_cast<int32_t>(mte2WaitMte3A));
367	    }
368	    LocalTensor<float> vecInBuffer3 =
369	        unifiedBuffer.GetWithOffset<float>(8 * 1024 / sizeof(float), ubBufferOffset + T2BlockBegin);
370	
371	    CopyInSoftMax(vecInBuffer3, s1Extend, softMaxOffset);
372	    LocalTensor<float> vecClc2Buffer =
373	        unifiedBuffer.GetWithOffset<float>(32 * 1024 / sizeof(float), ubBufferOffset + T2Begin);
374	    DataCopyPad(vecClc2Buffer, mm2WorkspaceGm[copyInOffset], copyInParam, {false, 0, 0, 0});
375	    event_t vWaitMte2 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_V));
376	    AscendC::SetFlag<HardEvent::MTE2_V>(static_cast<int32_t>(vWaitMte2));
377	    AscendC::WaitFlag<HardEvent::MTE2_V>(static_cast<int32_t>(vWaitMte2));
378	    AscendC::PipeBarrier<PIPE_V>();
379	    Muls(vecClc2Buffer, vecClc2Buffer, scaleValue, s1Extend * s2ExtendAlign);
380	
381	    AscendC::PipeBarrier<PIPE_V>();
382	    if (sparseMode != 0) {
383	        LocalTensor<uint8_t> attenMaskUbuint8 =
384	            unifiedBuffer.GetWithOffset<uint8_t>(16 * 1024 / sizeof(uint8_t), ubBufferOffset + BoolBegin);
385	        if (blockInfo.S1Idx == blockInfo.S2Idx) {
386	            CalcAttenMaskBool(vecClc2Buffer, attenMaskUbuint8[curS1Idx * s1VecSize * BASE_BLOCK_LENGTH], s1Extend,
387	                              s2ExtendAlign, S2_CUBESIZE, 0);
388	        }
389	    }
390	    ///////////////////////////////////////////////////////////////
391	    // simpleSoftMax
392	    ///////////////////////////////////////////////////////////////
393	    AscendC::PipeBarrier<PIPE_V>();
394	    LocalTensor<float> simpleSoftmaxResBuf = unifiedBuffer.GetWithOffset<float>(33 * 1024 / sizeof(float), DbBegin);
395	    CalcSoftMax(simpleSoftmaxResBuf, vecClc2Buffer, vecInBuffer3, s1Extend, s2Extend, s2ExtendAlign,
396	                tilingData->mlaTensorTilingData.softmaxTilingData);
397	    LocalTensor<float> vecDropBuffer = simpleSoftmaxResBuf;
398	    ///////////////////////////////////////////////////////////////
399	    // cast fp322bf16
400	    ///////////////////////////////////////////////////////////////
401	    LocalTensor<IN_TYPE> vecCopyOutBuffer =
402	        unifiedBuffer.GetWithOffset<IN_TYPE>(17 * 1024 / sizeof(IN_TYPE), ubBufferOffset + T1Begin);
403	    AscendC::PipeBarrier<PIPE_V>();
404	    Cast(vecCopyOutBuffer, vecDropBuffer, RoundMode::CAST_ROUND, s1Extend * s2ExtendAlign);
405	    event_t mte3WaitV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
406	    AscendC::SetFlag<HardEvent::V_MTE3>(static_cast<int32_t>(mte3WaitV));
407	    AscendC::WaitFlag<HardEvent::V_MTE3>(static_cast<int32_t>(mte3WaitV));
408	    DataCopyPad(dropWorkSpaceGm[copyOutOffset], vecCopyOutBuffer, copyOutParam);
409	    if (curIdx < blockLen - 1) {
410	        AscendC::SetFlag<HardEvent::MTE3_MTE2>(static_cast<int32_t>(mte2WaitMte3A));
411	    }
412	}
413	
414	template <typename IN_TYPE, class TILING_TYPE>
415	__aicore__ inline void VecOp<IN_TYPE, TILING_TYPE>::SubGrapB(int64_t curIdx, const VecBlockInfo &blockInfo,
416	                                                             event_t mte2WaitMte3B)
417	{
418	    uint32_t ubBufferOffset = DbBegin;
419	    if (curIdx > 0) {
420	        AscendC::WaitFlag<HardEvent::MTE3_MTE2>(static_cast<int32_t>(mte2WaitMte3B));
421	    }
422	    // copyIn sfmg
423	    LocalTensor<float> sfmgClc3 = unifiedBuffer.GetWithOffset<float>(SFMG_UB_SIZE / sizeof(float), SFMG_UB_OFFSET);
424	    DataCopy(sfmgClc3, sfmgWorkspaceGm[sfmgOffset], s1Extend * 8);
425	    LocalTensor<float> vecClc1Buffer =
426	        unifiedBuffer.GetWithOffset<float>(33 * 1024 / sizeof(float), ubBufferOffset + T1Begin);
427	
428	    // copyIn cube result
429	    DataCopyPad(vecClc1Buffer, mm1WorkspaceGm[copyInOffset], copyInParam, {false, 0, 0, 0});
430	    event_t vWaitMte2 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_V));
431	    AscendC::SetFlag<HardEvent::MTE2_V>(static_cast<int32_t>(vWaitMte2));
432	    AscendC::WaitFlag<HardEvent::MTE2_V>(static_cast<int32_t>(vWaitMte2));
433	    ///////////////////////////////////////////////////////////////
434	    // sub
435	    ///////////////////////////////////////////////////////////////
436	    uint32_t sub_block_cout = (s2ExtendAlign + cal_repeat_num - 1) / cal_repeat_num;
437	    AscendC::PipeBarrier<PIPE_V>();
438	    for (uint32_t subIdx = 0; subIdx < sub_block_cout; subIdx++) {
439	        uint32_t subMaskCout =
440	            (subIdx == sub_block_cout - 1) ? (s2ExtendAlign - subIdx * cal_repeat_num) : cal_repeat_num;
441	        Sub(vecClc1Buffer[subIdx * cal_repeat_num], vecClc1Buffer[subIdx * cal_repeat_num], sfmgClc3, subMaskCout,
442	            s1Extend,
443	            {static_cast<uint8_t>(1), static_cast<uint8_t>(1), 0, static_cast<uint8_t>(s2ExtendAlign / 8),
444	             static_cast<uint8_t>(s2ExtendAlign / 8), 1});
445	    }
446	    ///////////////////////////////////////////////////////////////
447	    // mul
448	    ///////////////////////////////////////////////////////////////
449	    AscendC::PipeBarrier<PIPE_V>();
450	    LocalTensor<float> simpleSoftmaxResBuf = unifiedBuffer.GetWithOffset<float>(32 * 1024 / sizeof(float), DbBegin);
451	    Mul(vecClc1Buffer, vecClc1Buffer, simpleSoftmaxResBuf, s1Extend * s2ExtendAlign);
452	    AscendC::PipeBarrier<PIPE_V>();
453	    LocalTensor<IN_TYPE> vecCopyOutBuffer =
454	        unifiedBuffer.GetWithOffset<IN_TYPE>(17 * 1024 / sizeof(IN_TYPE), ubBufferOffset + T1Begin);
455	    Cast(vecCopyOutBuffer, vecClc1Buffer, RoundMode::CAST_ROUND, s1Extend * s2ExtendAlign);
456	    event_t mte3WaitV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
457	    AscendC::SetFlag<HardEvent::V_MTE3>(static_cast<int32_t>(mte3WaitV));
458	    AscendC::WaitFlag<HardEvent::V_MTE3>(static_cast<int32_t>(mte3WaitV));
459	    // dyv = dp -> ds
460	    DataCopyPad(mulWorkSpaceGm[copyOutOffset], vecCopyOutBuffer, copyOutParam);
461	    if (curIdx < blockLen - 1) {
462	        AscendC::SetFlag<HardEvent::MTE3_MTE2>(static_cast<int32_t>(mte2WaitMte3B));
463	    }
464	}
465	#endif
