312	__aicore__ inline bool IsFullMaskBlock(const int32_t s1Idx, const int32_t s2Idx,
313	                                       const int32_t s1Len, const int32_t s2Len,
314	                                       const int32_t leftBound, const int32_t rightBound,
315	                                       const uint32_t sparseMode
316	                                      )
