326	    } else if (sparseMode == 4) {
327	        if (isRightUpBeyondTouchLeft(s1Idx, s2Idx + s2Len, leftBound)) {
328	            return true;
329	        }
330	        return isLeftDownOverTouchRight(s1Idx + s1Len, s2Idx, rightBound);
331	    }
