135	CubeOp<TYPE>::Cube1Compute(const AddrInfo &shapeInfo, __gm__ TYPE *left, __gm__ TYPE *right, __gm__ float *out)
136	{
137	    int32_t cube1Cnt = 0;
138	    int32_t km = shapeInfo.ky;
139	    int32_t kn = shapeInfo.kx;
