11	/*!
12	 * \file cube2_op.h
13	 * \brief
14	 */
15	#ifndef _CUBE2_OP_H_
16	#define _CUBE2_OP_H_
17	
18	template <typename TYPE>
19	__aicore__ inline __attribute__((always_inline)) void CubeOp<TYPE>::Cube2Compute(const AddrInfo &shapeInfo,
20	                                                                                 __gm__ TYPE *left, __gm__ TYPE *right,
21	                                                                                 __gm__ float *out, const bool isFisrt)
22	{
23	    // pingpongl1a/pingpongl0a 在1 * n情况下，恒为0，在2 * n情况下，0-1跳动
24	    // pingpongl1b/pingpongl0b 在1 * n情况和2 * n下，随n进行n % 2
25	    __gm__ TYPE *left_start_addr = left + (shapeInfo.out + globalBlockOffset) * 2;
26	    __gm__ TYPE *right_start_addr = right + shapeInfo.right;
27	    __gm__ float *result_gm = out + shapeInfo.left;
28	
29	    uint64_t left_offset = left_start_addr - (__gm__ TYPE *)0;
30	    uint64_t right_offset = right_start_addr - (__gm__ TYPE *)0;
31	    uint64_t out_offset = result_gm - (__gm__ float *)0;
32	
33	    // left matrix is (ky, kx)
34	    // right matrix is (kx, headDim)
35	    int32_t kn = shapeInfo.kx;
36	    int32_t km = shapeInfo.ky;
37	
38	    int32_t l1_m_size = km;
39	    int32_t l1_n_size = kn;
40	    int32_t l1_k_size = headDim;
41	
42	    int32_t l1_m_size_align = RoundUp(l1_m_size, C0_SIZE);
43	    int32_t l1_n_size_align = RoundUp(l1_n_size, C0_SIZE);
44	    int32_t l1_m_block_size_tail = (l1_m_size % 128) == 0 ? 128 : (l1_m_size % 128);
45	    int32_t l1_n_block_size_tail = (l1_n_size % 128) == 0 ? 128 : (l1_n_size % 128);
46	    int32_t l1_m_block_size_align_tail = (l1_m_size_align % 128) == 0 ? 128 : (l1_m_size_align % 128);
47	    int32_t l1_n_block_size_align_tail = (l1_n_size_align % 128) == 0 ? 128 : (l1_n_size_align % 128);
48	
49	    int32_t m_loop = CeilDiv(km, SIZE_128);
50	    int32_t n_loop = CeilDiv(kn, SIZE_128);
51	    bool upperRight = !shapeInfo.upperRight && sparseType != 0;
52	    int32_t startS1Id = shapeInfo.S1Idx;
53	    int32_t startS2Id = shapeInfo.S2Idx;
54	
55	    int32_t skip_num = 0;
56	    for (uint32_t n_loop_index = 0; n_loop_index < n_loop; n_loop_index++) {
57	        int32_t n_remain = (n_loop_index == n_loop - 1) ? l1_n_block_size_tail : 128;
58	        int32_t n_remain_align = (n_loop_index == n_loop - 1) ? l1_n_block_size_align_tail : 128;
59	        bool l0_c_init_flag = (n_loop_index == 0);
60	
61	        // load right matrix gm (kx, headDim)-> L1B
62	        AscendC::LocalTensor<TYPE> *l1_b_buf_tensor = ping_pong_flag_l1_b_ ? &l1_b_pong_tensor : &l1_b_ping_tensor;
63	        AscendC::WaitFlag<HardEvent::MTE1_MTE2>(static_cast<int32_t>(ping_pong_flag_l1_b_));
64	        commonNd2NzParams.nValue = n_remain;
65	        commonNd2NzParams.dValue = headDim;
66	        commonNd2NzParams.srcDValue = kvHeadNum * headDim;
67	        ;
68	        commonNd2NzParams.dstNzC0Stride = n_remain_align;
69	        AscendC::DataCopy(*l1_b_buf_tensor, temp_tensor_bf16[right_offset + n_loop_index * kvHeadNum * 128 * headDim],
70	                          commonNd2NzParams);
71	        AscendC::SetFlag<HardEvent::MTE2_MTE1>(static_cast<int32_t>(ping_pong_flag_l1_b_));
72	
73	        if (n_loop_index == 0 && isFisrt) {
74	            AscendC::WaitEvent(VEC2CUBE);
75	        }
76	
77	        // Load Left_GM matrix A -> L1A
78	        ping_pong_flag_l1_a_ = 0;
79	        for (uint32_t m_loop_index = 0; m_loop_index < m_loop; m_loop_index++) {
80	            AscendC::LocalTensor<TYPE> *l1_a_buf_tensor = ping_pong_flag_l1_a_ ? &l1_a_pong_tensor : &l1_a_ping_tensor;
81	            int32_t m_remain = (m_loop_index == m_loop - 1) ? l1_m_block_size_tail : 128;
82	            int32_t m_remain_align = (m_loop_index == m_loop - 1) ? l1_m_block_size_align_tail : 128;
83	            bool is_skip = false;
84	
85	            if (n_loop_index == n_loop - 1 && m_loop_index == 0 && upperRight) {
86	                skip_num++;
87	                is_skip = true;
88	            }
89	            AscendC::WaitFlag<HardEvent::MTE1_MTE2>(static_cast<int32_t>(ping_pong_flag_l1_a_ + 2));
90	            if (!is_skip) {
91	                commonNd2NzParams.dValue = n_remain;
92	                commonNd2NzParams.dstNzC0Stride = m_remain_align;
93	                commonNd2NzParams.srcDValue = 128;
94	                int32_t mUp = (m_remain + 1) / 2;
95	                int32_t mDown = m_remain - mUp;
96	
97	                commonNd2NzParams.nValue = mUp;
98	                AscendC::DataCopy(
99	                    *l1_a_buf_tensor,
100	                    temp_tensor_bf16[left_offset + 2 * (m_loop * n_loop_index + m_loop_index - skip_num) * 128 * 128],
101	                    commonNd2NzParams);
102	
103	                if (mDown > 0) {
104	                    commonNd2NzParams.nValue = mDown;
105	                    AscendC::DataCopy(
106	                        (*l1_a_buf_tensor)[mUp * C0_SIZE],
107	                        temp_tensor_bf16[left_offset +
108	                                         2 * (m_loop * n_loop_index + m_loop_index - skip_num) * 128 * 128 +
109	                                         2 * mUp * 128],
110	                        commonNd2NzParams);
111	                }
112	            }
113	            AscendC::SetFlag<HardEvent::MTE2_MTE1>(static_cast<int32_t>(ping_pong_flag_l1_a_ + 2));
114	            ping_pong_flag_l1_a_ = 1 - ping_pong_flag_l1_a_;
115	        }
116	
117	        // load L1B (n, headDim) -> L0B
118	        AscendC::LocalTensor<TYPE> *l0_b_buf_tensor = ping_pong_flag_l0_b_ ? &l0_b_pong_tensor : &l0_b_ping_tensor;
119	        commonLoadData2dParamsTranspose.repeatTimes = headDim / 16;
120	        commonLoadData2dParamsTranspose.srcStride = n_remain_align / 16;
121	        AscendC::WaitFlag<HardEvent::MTE2_MTE1>(static_cast<int32_t>(ping_pong_flag_l1_b_));
122	        AscendC::WaitFlag<HardEvent::M_MTE1>(static_cast<int32_t>(ping_pong_flag_l0_b_ + 2 + FLAG_SHIFT));
123	        for (int32_t i = 0; i < n_remain_align / 16; i++) {
124	            AscendC::LoadData((*l0_b_buf_tensor)[i * headDim * 16], (*l1_b_buf_tensor)[i * 16 * 16],
125	                              commonLoadData2dParamsTranspose);
126	        }
127	        AscendC::SetFlag<HardEvent::MTE1_M>(static_cast<int32_t>(ping_pong_flag_l0_b_ + 2));
128	        AscendC::SetFlag<HardEvent::MTE1_MTE2>(static_cast<int32_t>(ping_pong_flag_l1_b_));
129	
130	        ping_pong_flag_l1_a_ = 0;
131	        ping_pong_flag_l0_a_ = 0;
132	        AscendC::WaitFlag<HardEvent::MTE1_M>(static_cast<int32_t>(ping_pong_flag_l0_b_ + 2));
133	        // do m_loop times mad with l0B常驻
134	        for (uint32_t m_loop_index = 0; m_loop_index < m_loop; m_loop_index++) {
135	            AscendC::LocalTensor<TYPE> *l1_a_buf_tensor = ping_pong_flag_l1_a_ ? &l1_a_pong_tensor : &l1_a_ping_tensor;
136	            AscendC::LocalTensor<TYPE> *l0_a_buf_tensor = ping_pong_flag_l0_a_ ? &l0_a_pong_tensor : &l0_a_ping_tensor;
137	            AscendC::LocalTensor<float> *l0_c_buf_tensor = m_loop_index ? &l0_c_pong_tensor : &l0_c_ping_tensor;
138	
139	            int32_t m_remain = (m_loop_index == m_loop - 1) ? l1_m_block_size_tail : 128;
140	            int32_t m_remain_align = (m_loop_index == m_loop - 1) ? l1_m_block_size_align_tail : 128;
141	            bool is_skip = false;
142	
143	            if (n_loop_index == n_loop - 1 && m_loop_index == 0 && upperRight) {
144	                is_skip = true;
145	            }
146	            AscendC::WaitFlag<HardEvent::MTE2_MTE1>(static_cast<int32_t>(ping_pong_flag_l1_a_ + 2));
147	            AscendC::WaitFlag<HardEvent::M_MTE1>(static_cast<int32_t>(ping_pong_flag_l0_a_ + FLAG_SHIFT));
148	            if (!is_skip) {
149	                commonLoadData2dParamsNoTranspose.repeatTimes = n_remain_align / SIZE_16;
150	                commonLoadData2dParamsNoTranspose.srcStride = m_remain_align / SIZE_16;
151	                for (int32_t i = 0; i < m_remain_align / SIZE_16; i++) {
152	                    AscendC::LoadData((*l0_a_buf_tensor)[i * n_remain_align * 16], (*l1_a_buf_tensor)[i * 16 * 16],
153	                                      commonLoadData2dParamsNoTranspose);
154	                }
155	            }
156	            AscendC::SetFlag<HardEvent::MTE1_M>(static_cast<int32_t>(ping_pong_flag_l0_a_));
157	            AscendC::SetFlag<HardEvent::MTE1_MTE2>(static_cast<int32_t>(ping_pong_flag_l1_a_ + 2));
158	            bool last_k = false;
159	            last_k = (m_loop_index == 0 && upperRight) ? n_loop_index == n_loop - 2 : n_loop_index == n_loop - 1;
160	
161	            AscendC::WaitFlag<HardEvent::MTE1_M>(static_cast<int32_t>(ping_pong_flag_l0_a_));
162	            if (!is_skip) {
163	                uint16_t m_modify = (m_remain == 1) ? 2 : m_remain;
164	
165	                AscendC::Mmad(*l0_c_buf_tensor, *l0_a_buf_tensor, *l0_b_buf_tensor,
166	                              AscendC::MmadParams(m_modify, headDim, n_remain, last_k ? 3 : 2,
167	                                                  // unit_flag,
168	                                                  false, l0_c_init_flag));
169	            }
170	            AscendC::SetFlag<HardEvent::M_MTE1>(static_cast<int32_t>(ping_pong_flag_l0_a_ + FLAG_SHIFT));
171	
172	            // fixp in n_loop tail block
173	            if (!is_skip && last_k) {
174	                commonFixpipeParamsV220.mSize = m_remain;
175	                commonFixpipeParamsV220.nSize = headDim;
176	                commonFixpipeParamsV220.srcStride = m_remain_align;
177	                commonFixpipeParamsV220.dstStride = qHeadNum * headDim;
178	                AscendC::SetAtomicType<float>();
179	                AscendC::Fixpipe<float, float, AscendC::CFG_ROW_MAJOR>(
180	                    temp_tensor_fp32[out_offset + m_loop_index * qHeadNum * 128 * headDim], *l0_c_buf_tensor,
181	                    commonFixpipeParamsV220);
182	                AscendC::SetAtomicNone();
183	            }
184	            ping_pong_flag_l1_a_ = 1 - ping_pong_flag_l1_a_;
185	            ping_pong_flag_l0_a_ = 1 - ping_pong_flag_l0_a_;
186	        }
187	        AscendC::SetFlag<HardEvent::M_MTE1>(static_cast<int32_t>(ping_pong_flag_l0_b_ + 2 + FLAG_SHIFT));
188	
189	        ping_pong_flag_l0_b_ = 1 - ping_pong_flag_l0_b_;
190	        ping_pong_flag_l1_b_ = 1 - ping_pong_flag_l1_b_;
191	    }
192	}
193	#endif

