33	    int32_t l1_n_size_align = RoundUp(l1_n_size, C0_SIZE);
34	    int32_t l1_m_block_size_tail = (l1_m_size % 128) == 0 ? 128 : (l1_m_size % 128);
35	    int32_t l1_n_block_size_tail = (l1_n_size % 128) == 0 ? 128 : (l1_n_size % 128);
36	    int32_t l1_m_block_size_align_tail = (l1_m_size_align % 128) == 0 ? 128 : (l1_m_size_align % 128);
37	    int32_t l1_n_block_size_align_tail = (l1_n_size_align % 128) == 0 ? 128 : (l1_n_size_align % 128);
38	
39	    int32_t m_loop = CeilDiv(km, SIZE_128);
40	    int32_t n_loop = CeilDiv(kn, SIZE_128);
41	
42	    __gm__ TYPE *gm_a = left + (shapeInfo.out + globalBlockOffset) * 2;
43	    __gm__ TYPE *gm_b = right + shapeInfo.left;
44	    __gm__ float *gm_out = out + shapeInfo.right;
45	
46	    uint64_t left_offset = gm_a - (__gm__ TYPE *)0;
47	    uint64_t right_offset = gm_b - (__gm__ TYPE *)0;
48	    uint64_t out_offset = gm_out - (__gm__ float *)0;
49	
50	    LocalTensor<TYPE> *l1_b_buf_tensor = ping_pong_flag_l1_b_ ? &l1_b_pong_tensor : &l1_b_ping_tensor;
51	
52	    WAIT_FLAG(MTE1, MTE2, ping_pong_flag_l1_b_);
53	
54	    commonNd2NzParams.nValue = l1_m_size;
55	    commonNd2NzParams.dValue = headDim;
56	    commonNd2NzParams.dstNzC0Stride = l1_m_size_align;
57	    commonNd2NzParams.srcDValue = qHeadNum * headDim;
58	    AscendC::DataCopy((*l1_b_buf_tensor)[0], temp_tensor_bf16[right_offset], commonNd2NzParams);
59	
60	    SET_FLAG(MTE2, MTE1, ping_pong_flag_l1_b_);
61	    WAIT_FLAG(MTE2, MTE1, ping_pong_flag_l1_b_);
62	
63	    uint32_t blockId[16];
64	
65	    uint32_t count = 0;
66	    for (uint32_t m_loop_index = 0; m_loop_index < m_loop; m_loop_index += 2) {
67	        for (uint32_t n_loop_index = 0; n_loop_index < n_loop; n_loop_index++) {
68	            int32_t loop_limit = (m_loop_index + 2 > m_loop) ? 1 : 2;
69	            for (int j = 0; j < loop_limit; j++) {
70	                if (sparseType == 0 || s1Idx + m_loop_index + j >= s2Idx + n_loop_index) {
71	                    blockId[n_loop_index * m_loop + m_loop_index + j] = count;
72	                    count += 1;
73	                } else {
74	                    blockId[n_loop_index * m_loop + m_loop_index + j] = 17;
75	                }
76	            }
77	        }
78	    }
79	
80	    // n: k方向
81	    // m: q方向
82	    for (uint32_t n_loop_index = 0; n_loop_index < n_loop; n_loop_index++) {
83	        // mmad 按m方向累加，Q方向
84	        for (uint32_t m_loop_index = 0; m_loop_index < m_loop; m_loop_index++) {
85	            bool is_skip = false;
86	            if (sparseType != 0 && s2Idx + n_loop_index > s1Idx + m_loop_index) {
87	                is_skip = true;
88	                continue;
89	            }
90	
91	            LocalTensor<TYPE> *l1_a_buf_tensor = ping_pong_flag_l1_a_ ? &l1_a_pong_tensor : &l1_a_ping_tensor;
92	            LocalTensor<TYPE> *l0_a_buf_tensor = ping_pong_flag_l0_a_ ? &l0_a_pong_tensor : &l0_a_ping_tensor;
93	            LocalTensor<TYPE> *l0_b_buf_tensor = (ping_pong_flag_l0_b_last) ? &l0_b_ping_tensor : &l0_b_pong_tensor;
94	            LocalTensor<float> *l0_c_buf_tensor = ping_pong_flag_l0_c_ ? &l0_c_pong_tensor : &l0_c_ping_tensor;
95	
96	            if (!is_skip) {
97	                WAIT_FLAG(M, MTE1, ping_pong_flag_l0_b_last + 2 + FLAG_SHIFT);
98	                commonLoadData2dParamsTranspose.repeatTimes = headDim / 16;
99	                commonLoadData2dParamsTranspose.srcStride = l1_m_size_align / 16;
100	
101	                int32_t m_remain = (m_loop_index == m_loop - 1) ? l1_m_block_size_align_tail : 128;
102	                int32_t l1_b_buf_offset = 128 * 16 * m_loop_index;
103	
104	                for (int32_t j = 0; j < m_remain / 16; j++) {
105	                    AscendC::LoadData((*l0_b_buf_tensor)[j * headDim * 16],
106	                                      (*l1_b_buf_tensor)[l1_b_buf_offset + j * 16 * 16],
107	                                      commonLoadData2dParamsTranspose);
108	                }
109	                SET_FLAG(MTE1, M, ping_pong_flag_l0_b_last + 2);
110	                WAIT_FLAG(MTE1, M, ping_pong_flag_l0_b_last + 2);
111	            }
112	
113	            uint32_t real_m = (m_loop_index == m_loop - 1) ? l1_m_block_size_tail : 128;
114	            uint32_t real_n = (n_loop_index == n_loop - 1) ? l1_n_block_size_tail : 128;
115	            uint32_t real_m_align = (m_loop_index == m_loop - 1) ? l1_m_block_size_align_tail : 128;
116	            uint32_t real_n_align = (n_loop_index == n_loop - 1) ? l1_n_block_size_align_tail : 128;
117	
118	            bool init_c = (m_loop_index == 0 || (sparseType != 0 && (s2Idx + n_loop_index == s1Idx + m_loop_index)));
119	            bool out_c = (m_loop_index == (m_loop - 1));
120	
121	            if (!is_skip) {
122	                WAIT_FLAG(MTE1, MTE2, ping_pong_flag_l1_a_ + 2);
123	                commonNd2NzParams.dValue = real_n;
124	                commonNd2NzParams.dstNzC0Stride = real_m_align;
125	                commonNd2NzParams.srcDValue = 128;
126	                int32_t mUp = (real_m + 1) / 2;
127	                int32_t mDown = real_m - mUp;
128	
129	                commonNd2NzParams.nValue = mUp;
130	                AscendC::DataCopy(*l1_a_buf_tensor,
131	                                  temp_tensor_bf16[left_offset + 2 * blockId[(n_loop_index * m_loop + m_loop_index)] *
132	                                                                     SIZE_128 * SIZE_128],
133	                                  commonNd2NzParams);
134	
135	                if (mDown > 0) {
136	                    commonNd2NzParams.nValue = mDown;
137	                    AscendC::DataCopy(
138	                        (*l1_a_buf_tensor)[C0_SIZE * mUp],
139	                        temp_tensor_bf16[left_offset +
140	                                         2 * blockId[(n_loop_index * m_loop + m_loop_index)] * SIZE_128 * SIZE_128 +
141	                                         2 * mUp * 128],
142	                        commonNd2NzParams);
143	                }
144	
145	                SET_FLAG(MTE2, MTE1, ping_pong_flag_l1_a_ + 2);
146	                WAIT_FLAG(MTE2, MTE1, ping_pong_flag_l1_a_ + 2);
147	            }
148	
149	            if (!is_skip) {
150	                WAIT_FLAG(M, MTE1, ping_pong_flag_l0_a_ + FLAG_SHIFT);
151	                // load left matrix dS(kx, ky) from L1A to L0A
152	                uint32_t m_c0_loop = (real_m + 15) / 16;
153	                uint32_t n_c0_loop = (real_n + 15) / 16;
154	                commonLoadData2dParamsTranspose.repeatTimes = m_c0_loop * n_c0_loop;
155	                commonLoadData2dParamsTranspose.srcStride = 1;
156	                AscendC::LoadData((*l0_a_buf_tensor), (*l1_a_buf_tensor), commonLoadData2dParamsTranspose);
157	
158	                SET_FLAG(MTE1, MTE2, ping_pong_flag_l1_a_ + 2);
159	            }
160	            if (!is_skip) {
161	                SET_FLAG(MTE1, M, ping_pong_flag_l0_a_);
162	                WAIT_FLAG(MTE1, M, ping_pong_flag_l0_a_);
163	                int unit_flag = 0b10;
164	
165	                if (out_c) {
166	                    unit_flag = 0b11;
167	                }
168	
169	                commonMadParams.m = real_n == 1 ? 2 : real_n;
170	                commonMadParams.n = headDim;
171	                commonMadParams.k = real_m;
172	                commonMadParams.unitFlag = unit_flag;
173	                commonMadParams.cmatrixInitVal = init_c;
174	                AscendC::Mmad(*l0_c_buf_tensor, *l0_a_buf_tensor, *l0_b_buf_tensor, commonMadParams);
175	                SET_FLAG(M, MTE1, ping_pong_flag_l0_b_last + 2 + FLAG_SHIFT);
176	
177	                PipeBarrier<PIPE_M>();
178	                ping_pong_flag_l0_b_last = 1 - ping_pong_flag_l0_b_last;
179	
180	                SET_FLAG(M, MTE1, ping_pong_flag_l0_a_ + FLAG_SHIFT);
181	            }
182	
183	            if (!is_skip && out_c) {
184	                commonFixpipeParamsV220.mSize = real_n;
185	                commonFixpipeParamsV220.nSize = headDim;
186	                commonFixpipeParamsV220.srcStride = real_n_align;
187	                commonFixpipeParamsV220.dstStride = headDim * kvHeadNum;
188	                AscendC::SetAtomicType<float>();
189	                AscendC::Fixpipe<float, float, AscendC::CFG_ROW_MAJOR>(
190	                    temp_tensor_fp32[out_offset + n_loop_index * 128 * kvHeadNum * headDim], *l0_c_buf_tensor,
191	                    commonFixpipeParamsV220);
192	                AscendC::SetAtomicNone();
193	            }
194	
195	            ping_pong_flag_l1_a_ = 1 - ping_pong_flag_l1_a_;
196	            ping_pong_flag_l0_a_ = 1 - ping_pong_flag_l0_a_;
197	        }
198	
199	        ping_pong_flag_l0_c_ = 1 - ping_pong_flag_l0_c_;
200	    }
201	    SET_FLAG(MTE1, MTE2, ping_pong_flag_l1_b_);
202	    ping_pong_flag_l1_b_ = 1 - ping_pong_flag_l1_b_;
203	}
204	#endif

