28	constexpr int64_t ATTEN_MASK_DIM_NUM = 2;
29	constexpr int64_t ATTEN_MASK_NUM = 2048;
30	constexpr int64_t S_MAX = 32768;
31	constexpr int64_t DIM_NUM_2 = 2;
32	constexpr int64_t SPECIAL_HEADDIM_128 = 128;
