46	ge::graphStatus FlashAttentionScoreGraTilingMla::SetAttrsInfo()
47	{
48	    // option input
49	    auto pseShape = context_->GetOptionalInputShape(PSE_SHIFT);
50	    auto dropMask = context_->GetOptionalInputShape(DROP_MASK);
51	    auto attenMaskShape = context_->GetOptionalInputShape(ATTEN_MASK);
52	
53	    fBaseParams.attenMskEnable = attenMaskShape != nullptr;
54	    if (fBaseParams.attenMskEnable) {
55	        auto storageShape = attenMaskShape->GetStorageShape();
56	        auto maskShapeDims = storageShape.GetDimNum();
57	        if (maskShapeDims != ATTEN_MASK_DIM_NUM) {
58	            OP_LOGI(
59	                context_, "FlashAttentionScoreGradEnhanceMla not support attenMaskShape dim num: %lu", maskShapeDims);
60	            return ge::GRAPH_PARAM_INVALID;
61	        }
62	
63	        auto dim0 = storageShape.GetDim(0);
64	        auto dim1 = storageShape.GetDim(1);
65	        if ((dim0 != ATTEN_MASK_NUM) && (dim1 != ATTEN_MASK_NUM)) {
66	            OP_LOGI(context_, "FlashAttentionScoreGradEnhanceMla attenMaskShape should be 2048 * 2048.");
67	            return ge ::GRAPH_PARAM_INVALID;
68	        }
69	    }
70	
71	    // attr
72	    fBaseParams.scaleValue = *context_->GetAttrs()->GetAttrPointer<float>(SCALE_VALUE);
73	    fBaseParams.keepProb = *context_->GetAttrs()->GetAttrPointer<float>(KEEP_PROB);
74	    fBaseParams.inputLayout = context_->GetAttrs()->GetAttrPointer<char>(INPUT_LAYOUT);
75	    fBaseParams.sparseMode = *context_->GetAttrs()->GetAttrPointer<int>(SPARSE_MODE);
76	
77	    OP_CHECK_IF((fBaseParams.keepProb <= 0 || fBaseParams.keepProb > 1),
78	                OP_LOGE(context_, "keepProb is illegal."),
79	                return ge::GRAPH_FAILED);
80	
81	    fBaseParams.dropMskEnable = (dropMask != nullptr || fBaseParams.keepProb < 1.0f);
82	    if (context_->GetAttrs()->GetAttrNum() > static_cast<size_t>(PSETYPE)) {
83	        auto pseType = *context_->GetAttrs()->GetAttrPointer<int>(PSETYPE);
84	        fBaseParams.pseEnable = (pseShape != nullptr || pseType != 1);
85	    }
86	
87	    return ge::GRAPH_SUCCESS;
88	}
89	
90	ge::graphStatus FlashAttentionScoreGraTilingMla::SetBaseInfo()
91	{
92	    if (strcmp(fBaseParams.inputLayout, TND_STR) != 0) {
93	        OP_LOGI(context_,
94	                "FlashAttentionScoreGradEnhanceMla only support TND inputLayout, now is %s.",
95	                fBaseParams.inputLayout);
96	        return ge ::GRAPH_PARAM_INVALID;
97	    }
98	    const gert::StorageShape *queryShape = context_->GetInputShape(0);
99	    const gert::StorageShape *keyShape = context_->GetInputShape(1);
100	    const gert::StorageShape *valueShape = context_->GetInputShape(2);
101	
102	    auto actualSeqQLenTensor = context_->GetOptionalInputTensor(ACTUAL_SEQ_Q_LEN);
103	    auto actualSeqKvLenTensor = context_->GetOptionalInputTensor(ACTUAL_SEQ_KV_LEN);
104	    auto qStartTensor = context_->GetOptionalInputTensor(Q_START_IDX);
105	    auto kvStartTensor = context_->GetOptionalInputTensor(KV_START_IDX);
106	
107	    if (actualSeqQLenTensor == nullptr || actualSeqKvLenTensor == nullptr) {
108	        OP_LOGE(context_, "actualSeqQLenTensor or actualSeqKvLenTensor is nullptr");
109	        return ge::GRAPH_FAILED;
110	    }
111	    if (qStartTensor != nullptr || kvStartTensor != nullptr) {
112	        OP_LOGI(context_, "FlashAttentionScoreGradEnhanceMla not support q_start_idx or kv_start_idx.");
113	        return ge::GRAPH_PARAM_INVALID;
114	    }
115	
116	    const int64_t *qValue = actualSeqQLenTensor->GetData<int64_t>();
117	    const int64_t *kvValue = actualSeqKvLenTensor->GetData<int64_t>();
118	    const size_t seqQShapeSize = static_cast<size_t>(actualSeqQLenTensor->GetShapeSize());
119	    const size_t kvSeqShapeSize = static_cast<size_t>(actualSeqKvLenTensor->GetShapeSize());
120	
121	    OP_CHECK_IF((qValue == nullptr || kvValue == nullptr),
122	                OP_LOGE(context_, "qValue or kvValue is nullptr."),
123	                return ge::GRAPH_FAILED);
124	    OP_CHECK_IF((seqQShapeSize != kvSeqShapeSize),
125	                OP_LOGE(context_, "actualSeqQLenTensor shapeSize is not equal actualSeqKvLenTensor"),
126	                return ge::GRAPH_FAILED);
127	
128	    for (size_t i = 0; i < seqQShapeSize; i++) {
129	        int64_t qSeqLen = (i == 0 ? qValue[i] : (qValue[i] - qValue[i - 1]));
130	        int64_t kvSeqLen = (i == 0 ? kvValue[i] : (kvValue[i] - kvValue[i - 1]));
131	        fBaseParams.actualSeqQlen.push_back(qSeqLen);
132	        fBaseParams.actualSeqKvlen.push_back(kvSeqLen);
133	        if (qSeqLen != kvSeqLen) {
134	            fBaseParams.eaqualActSeqLen = false;
135	        }
136	    }
137	
138	    uint64_t tailZeroCount = 0;
139	    for (auto i = seqQShapeSize - 1; i >= 1; --i) {
140	        if (fBaseParams.actualSeqQlen[i] > 0 && fBaseParams.actualSeqKvlen[i] > 0) {
141	            break;
142	        }
143	        ++tailZeroCount;
144	    }
145	
146	    // base shape
147	    fBaseParams.b = seqQShapeSize - tailZeroCount;
148	    fBaseParams.queryType = static_cast<uint32_t>(context_->GetInputDesc(QUERY)->GetDataType());
149	    fBaseParams.t1 = queryShape->GetStorageShape().GetDim(0);
150	    fBaseParams.t2 = keyShape->GetStorageShape().GetDim(0);
151	    fBaseParams.n1 = queryShape->GetStorageShape().GetDim(1);
152	    fBaseParams.n2 = keyShape->GetStorageShape().GetDim(1);
153	    fBaseParams.d = queryShape->GetStorageShape().GetDim(DIM_NUM_2);
154	    fBaseParams.dv = valueShape->GetStorageShape().GetDim(DIM_NUM_2);
155	    OP_CHECK_IF(fBaseParams.n2 == 0, OP_LOGE(context_, "dim N2 is 0."), return ge::GRAPH_FAILED);
156	    fBaseParams.g = fBaseParams.n1 / fBaseParams.n2;
157	    fBaseParams.s1 = *std::max_element(fBaseParams.actualSeqQlen.begin(), fBaseParams.actualSeqQlen.end());
158	    fBaseParams.s1 = *std::max_element(fBaseParams.actualSeqKvlen.begin(), fBaseParams.actualSeqKvlen.end());
159	
160	    return CheckTndShapeValid(context_, fBaseParams.t1, fBaseParams.n1, fBaseParams.d);
161	}
162	
163	bool FlashAttentionScoreGraTilingMla::IsCapable()
164	{
165	    /**
166	     * The basic template does not support the following features:
167	     * 1. The dtype of float32
168	     * 2. Layouts other than TND
169	     * 3. Deterministic
170	     * 4. Sparse mode not equal to 0 or 2 or 3
171	     * 5. PSE
172	     * 6. Drop mask
173	     */
174	    auto sinkShape = context_->GetOptionalInputShape(SINK_IN);
175	    if (sinkShape != nullptr && sinkShape->GetStorageShape().GetDimNum() == 1) {
176	        return false;
177	    }
178	    if (fBaseParams.queryType == ge::DT_FLOAT) {
179	        OP_LOGI(context_, "FlashAttentionScoreGradEnhanceMla does not support float32.");
180	        return false;
181	    } else if (strcmp(fBaseParams.inputLayout, TND_STR) != 0) {
182	        OP_LOGI(context_,
183	                "FlashAttentionScoreGradEnhanceMla does not support Layouts other than TND, now is %s.",
184	                fBaseParams.inputLayout);
185	        return false;
186	    } else if (context_->GetDeterministic() == 1) {
187	        OP_LOGI(context_, "FlashAttentionScoreGradEnhanceMla does not support deterministic.");
188	        return false;
189	    } else if (fBaseParams.pseEnable) {
190	        OP_LOGI(context_, "FlashAttentionScoreGradEnhanceMla does not support PSE feature.");
191	        return false;
192	    } else if (fBaseParams.dropMskEnable) {
193	        OP_LOGI(context_, "FlashAttentionScoreGradEnhanceMla does not support dropMask feature.");
194	        return false;
195	    } else if (!IsAttenMskCapable()) {
196	        return false;
197	    }
198	
199	    if (!IsShapeCapable()) {
200	        OP_LOGI(context_, "FlashAttentionScoreGradEnhanceMla does not support current input shape.");
201	        return false;
202	    }
203	
204	    OP_LOGI(context_, "FlashAttentionScoreGradEnhanceMla is capable.");
205	    return true;
206	}
207	
208	bool FlashAttentionScoreGraTilingMla::IsAttenMskCapable()
209	{
210	    if (fBaseParams.sparseMode != NO_MASK && fBaseParams.sparseMode != RIGHT_DOWN_CAUSAL &&
211	        fBaseParams.sparseMode != LEFT_UP_CAUSAL) {
212	        OP_LOGI(context_,
213	                "FlashAttentionScoreGradEnhanceMla only support sparseMode=%d or %d or %d, now is %u.",
214	                NO_MASK,
215	                LEFT_UP_CAUSAL,
216	                RIGHT_DOWN_CAUSAL,
217	                fBaseParams.sparseMode);
218	        return false;
219	    } else if (fBaseParams.sparseMode == NO_MASK && fBaseParams.attenMskEnable) {
220	        OP_LOGI(context_,
221	                "FlashAttentionScoreGradEnhanceMla sparseMode=%u, but attenMask is exsit.",
222	                fBaseParams.sparseMode);
223	        return false;
224	    } else if (fBaseParams.sparseMode == LEFT_UP_CAUSAL && !fBaseParams.attenMskEnable) {
225	        OP_LOGI(context_,
226	                "FlashAttentionScoreGradEnhanceMla sparseMode=%u, but attenMask is nullptr.",
227	                fBaseParams.sparseMode);
228	        return false;
229	    } else if (fBaseParams.sparseMode == RIGHT_DOWN_CAUSAL && !fBaseParams.attenMskEnable) {
230	        OP_LOGI(context_,
231	                "FlashAttentionScoreGradEnhanceMla sparseMode=%u, but attenMask is nullptr.",
232	                fBaseParams.sparseMode);
233	        return false;
234	    }
235	
236	    return true;
237	}
238	
239	bool FlashAttentionScoreGraTilingMla::IsShapeCapable()
240	{
241	    if (fBaseParams.d != fBaseParams.dv || fBaseParams.d > SPECIAL_HEADDIM_128 || fBaseParams.d % C0_SIZE != 0) {
242	        return false;
243	    }
244	
245	    if (fBaseParams.t1 != fBaseParams.t2 || !fBaseParams.eaqualActSeqLen || fBaseParams.s1 > S_MAX) {
246	        return false;
247	    }
248	
249	    return true;
250	}
