252	ge::graphStatus FlashAttentionScoreGraTilingMla::DoOpTiling()
253	{
254	    auto compileInfoPtr = context_->GetCompileInfo<MultiHeadLatentAttentionGradCompileInfo>();
255	
256	    int64_t qSize = fBaseParams.t1 * fBaseParams.n1 * fBaseParams.d;
257	    int64_t kvSize = fBaseParams.t2 * fBaseParams.n2 * fBaseParams.d;
258	    int64_t sfmgSize = fBaseParams.t1 * fBaseParams.n1 * 8;
259	    uint32_t vectorCoreNum = compileInfoPtr->aivNum;
260	
261	    tilingData->mlaTensorTilingData.SetCoreNum(vectorCoreNum);
262	    tilingData->mlaTensorTilingData.SetScaleValue(fBaseParams.scaleValue);
263	    tilingData->mlaTensorTilingData.SetB(fBaseParams.b);
264	    tilingData->mlaTensorTilingData.SetT1(fBaseParams.t1);
265	    tilingData->mlaTensorTilingData.SetT2(fBaseParams.t2);
266	    tilingData->mlaTensorTilingData.SetN2(fBaseParams.n2);
267	    tilingData->mlaTensorTilingData.SetG(fBaseParams.g);
268	    tilingData->mlaTensorTilingData.SetD(fBaseParams.d);
269	    tilingData->mlaTensorTilingData.SetQSize(qSize);
270	    tilingData->mlaTensorTilingData.SetKvSize(kvSize);
271	    tilingData->mlaTensorTilingData.SetSfmgSize(sfmgSize);
272	    tilingData->mlaTensorTilingData.SetSparseMode(fBaseParams.sparseMode);
273	    bool tndSoftmaxIn = context_->GetAttrs()->GetAttrNum() > static_cast<size_t>(TND_SOFTMAX_IN)
274	                            ? *(context_->GetAttrs()->GetAttrPointer<bool>(TND_SOFTMAX_IN))
275	                            : false;
276	    if (tndSoftmaxIn) {
277	        tilingData->mlaTensorTilingData.SetTndSoftmaxIn(1);
278	    } else {
279	        tilingData->mlaTensorTilingData.SetTndSoftmaxIn(0);
280	    }
281	    return ge::GRAPH_SUCCESS;
282	}
283	
284	ge::graphStatus FlashAttentionScoreGraTilingMla::DoLibApiTiling()
285	{
286	    constexpr uint32_t tmpBufferSize = 33 * 1024;
287	    constexpr uint32_t s1VecSize = 64;
288	    constexpr uint32_t s2VecSize = 128;
289	    int64_t d = tilingData->mlaTensorTilingData.GetD();
290	    auto softmaxShape = ge::Shape({s1VecSize, s2VecSize});
291	    AscendC::SoftMaxTilingFunc(
292	        softmaxShape, sizeof(float), tmpBufferSize, tilingData->mlaTensorTilingData.softmaxTilingData);
293	
294	    // softmaxGrad tiling
295	    constexpr uint32_t inputBufferLen = 24 * 1024;
296	    constexpr uint32_t castBufferLen = 48 * 1024; // castBuffer 48K*2=96K
297	    // uint32_t outputBufferLen = CeilDiv(castBufferLen, d) * 8; // 输出(s1,8)
298	    uint32_t outputBufferLen = (castBufferLen + d - 1) / d * 8; // 输出(s1,8)
299	    uint32_t tempBufferLen = 40 * 1024 - outputBufferLen;
300	
301	    int64_t singleLoopNBurstNum = inputBufferLen / sizeof(float) / d;
302	    auto softmaxGradShape = ge::Shape({singleLoopNBurstNum, d});
303	    AscendC::SoftMaxGradTilingFunc(
304	        softmaxGradShape, sizeof(float), tempBufferLen, tilingData->mlaTensorTilingData.softmaxGradTilingData, true);
305	
306	    return ge::GRAPH_SUCCESS;
307	}
