322	ge::graphStatus FlashAttentionScoreGraTilingMla::GetWorkspaceSize()
323	{
324	    auto compileInfoPtr = context_->GetCompileInfo<MultiHeadLatentAttentionGradCompileInfo>();
325	    uint32_t cubeCoreNum = compileInfoPtr->aicNum;
326	    constexpr size_t WORKSPACE_RSV_BYTE = 16 * 1024 * 1024;
327	    constexpr size_t GM_ALIGN = 512;
328	    constexpr size_t DB_NUM = 2;
329	    constexpr size_t matmulSize = 16 * 128 * 128;
330	
331	    size_t *workspaces = context_->GetWorkspaceSizes(1);
332	    size_t workspaceOffset = WORKSPACE_RSV_BYTE;
333	
334	    // matmal3 q
335	    tilingData->mlaTensorTilingData.SetDqWorkSpaceOffset(workspaceOffset);
336	    workspaceOffset =
337	        (workspaceOffset + tilingData->mlaTensorTilingData.GetQSize() * sizeof(float) + GM_ALIGN) / GM_ALIGN * GM_ALIGN;
338	    // matmal3 k
339	    tilingData->mlaTensorTilingData.SetDkWorkSpaceOffset(workspaceOffset);
340	    workspaceOffset = (workspaceOffset + tilingData->mlaTensorTilingData.GetKvSize() * sizeof(float) + GM_ALIGN) /
341	                      GM_ALIGN * GM_ALIGN;
342	    // matmal3 v
343	    tilingData->mlaTensorTilingData.SetDvWorkSpaceOffset(workspaceOffset);
344	    workspaceOffset = (workspaceOffset + tilingData->mlaTensorTilingData.GetKvSize() * sizeof(float) + GM_ALIGN) /
345	                      GM_ALIGN * GM_ALIGN;
346	    // sfmg workspace
347	    tilingData->mlaTensorTilingData.SetSfmgWorkspaceOffset(workspaceOffset);
348	    workspaceOffset = (workspaceOffset + tilingData->mlaTensorTilingData.GetSfmgSize() * sizeof(float) + GM_ALIGN) /
349	                      GM_ALIGN * GM_ALIGN;
350	
351	    // matmal1/matmal2 workspace size
352	    tilingData->mlaTensorTilingData.SetMm1WorkspaceOffset(workspaceOffset);
353	    workspaceOffset =
354	        (workspaceOffset + cubeCoreNum * matmulSize * sizeof(float) * DB_NUM + GM_ALIGN) / GM_ALIGN * GM_ALIGN;
355	
356	    tilingData->mlaTensorTilingData.SetMm2WorkspaceOffset(workspaceOffset);
357	    workspaceOffset =
358	        (workspaceOffset + cubeCoreNum * matmulSize * sizeof(float) * DB_NUM + GM_ALIGN) / GM_ALIGN * GM_ALIGN;
359	
360	    workspaceOffset += WORKSPACE_RSV_BYTE;
361	    // set workspace
362	    workspaces[0] = (workspaceOffset - 0);
363	
364	    return ge::GRAPH_SUCCESS;
365	}
