378	ge::graphStatus FlashAttentionScoreGraTilingMla::GetPlatformInfo()
379	{
380	    auto platformInfoPtr = context_->GetPlatformInfo();
381	    if (platformInfoPtr == nullptr) {
382	        auto compileInfoPtr =
383	            reinterpret_cast<const Ops::Transformer::OpTiling::FlashAttentionScoreGradEnhanceCompileInfo *>(
384	                context_->GetCompileInfo());
385	        OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(context_, "compile_info is null"), return ge::GRAPH_FAILED);
386	
387	        aicoreParams_.blockDim = compileInfoPtr->aivNum;
388	        aicoreParams_.aicNum = compileInfoPtr->aicNum;
389	        aicoreParams_.ubSize = compileInfoPtr->ubSize;
390	        aicoreParams_.l1Size = compileInfoPtr->l1Size;
391	        aicoreParams_.l0aSize = compileInfoPtr->l0aSize;
392	        aicoreParams_.l0bSize = compileInfoPtr->l0bSize;
393	        aicoreParams_.l0cSize = compileInfoPtr->l0cSize;
394	    } else {
395	        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
396	        aicoreParams_.blockDim = ascendcPlatform.GetCoreNumAiv();
397	        aicoreParams_.aicNum = ascendcPlatform.GetCoreNumAic();
398	        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, aicoreParams_.ubSize);
399	        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, aicoreParams_.l1Size);
400	        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_A, aicoreParams_.l0aSize);
401	        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_B, aicoreParams_.l0bSize);
402	        ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, aicoreParams_.l0cSize);
403	    }
404	
405	    OP_CHECK_IF((aicoreParams_.blockDim == 0) || (aicoreParams_.aicNum == 0),
406	                OP_LOGE(context_,
407	                        "num of coreNum(aivNum) is %lu, num of aicNum is %lu.",
408	                        aicoreParams_.blockDim,
409	                        aicoreParams_.aicNum),
410	                return ge::GRAPH_FAILED);
411	
412	    return ge::GRAPH_SUCCESS;
413	}
