177	template <typename TYPE, class TILING_CLASS>
178	__aicore__ inline void
179	FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::CubeProcess(GM_ADDR query,
180	                                                                     GM_ADDR key,
181	                                                                     GM_ADDR value,
182	                                                                     GM_ADDR dy,
183	                                                                     GM_ADDR atten_mask,
184	                                                                     GM_ADDR softmax_max,
185	                                                                     GM_ADDR softmax_sum,
186	                                                                     GM_ADDR attention_in,
187	                                                                     GM_ADDR actual_seq_qlen,
188	                                                                     GM_ADDR actual_seq_kvlen,
189	                                                                     GM_ADDR dq,
190	                                                                     GM_ADDR dk,
191	                                                                     GM_ADDR dv,
192	                                                                     GM_ADDR user,
193	                                                                     const TILING_CLASS *tilingData)
194	{
195	    AscendC::TPipe pipeCube;
196	    CUBE_OP::CubeOp<TYPE> cubeOp;
197	    CUBE_ADDR::CubeAddr cubeAddr;
198	    struct CubeAddrInfo cubeAddrInfo[2];
199	    struct CubeAddrInfo cube3AddrInfo[2];
200	    int32_t taskId = 0;
201	    bool running = true;
202	    // cube2 and cube3 mix when headDim is 64 and sparseMode is 0
203	    bool cube23_mix_flag = (sparseMode == 0 && headDim == 64);
204	
205	    cubeOp.Init(&pipeCube, n1, n2, headDim, sparseMode);
206	    cubeAddr.init(batch, n1, g, headDim, GetBlockIdx(), actual_seq_qlen, actual_seq_kvlen, mixCoreNum, sparseMode);
207	
208	    while (running) {
209	        cubeAddrInfo[taskId % 2].taskId = taskId;
210	        cube3AddrInfo[taskId % 2].taskId = taskId;
211	        cubeAddr.addr_mapping(&cubeAddrInfo[taskId % 2], &cube3AddrInfo[taskId % 2]);
212	        if (cubeAddrInfo[taskId % 2].blockLength > 0) {
213	            SetFlag();
214	            cubeOp.Cube1Process(
215	                cubeAddrInfo[taskId % 2], (__gm__ TYPE *)query, (__gm__ TYPE *)key, (__gm__ float *)mm2WorkSpaceAddr);
216	            cubeOp.Cube1Process(
217	                cubeAddrInfo[taskId % 2], (__gm__ TYPE *)dy, (__gm__ TYPE *)value, (__gm__ float *)mm1WorkSpaceAddr);
218	            WaitFlag();
219	            AscendC::CrossCoreSetFlag<2, PIPE_FIX>(CUBE2VEC);
220	        }
221	        if (taskId > 0 && cubeAddrInfo[(taskId - 1) % 2].blockLength > 0) {
222	            if (cube23_mix_flag) {
223	                AscendC::WaitEvent(VEC2CUBE);
224	                SetFlag();
225	                cubeOp.Cube23Process(cubeAddrInfo[(taskId - 1) % 2],
226	                                     (__gm__ TYPE *)mm1WorkSpaceAddr,
227	                                     (__gm__ TYPE *)key,
228	                                     (__gm__ TYPE *)query,
229	                                     (__gm__ float *)dqWorkSpaceAddr,
230	                                     (__gm__ float *)dkWorkSpaceAddr);
231	                WaitFlag();
232	                SetFlag();
233	                cubeOp.Cube3Process(cube3AddrInfo[(taskId - 1) % 2],
234	                                    (__gm__ TYPE *)mm2WorkSpaceAddr,
235	                                    (__gm__ TYPE *)dy,
236	                                    (__gm__ float *)dvWorkSpaceAddr);
237	                WaitFlag();
238	            } else {
239	                SetFlag();
240	                cubeOp.Cube2Process(cubeAddrInfo[(taskId - 1) % 2],
241	                                    (__gm__ TYPE *)mm1WorkSpaceAddr,
242	                                    (__gm__ TYPE *)key,
243	                                    (__gm__ float *)dqWorkSpaceAddr);
244	                WaitFlag();
245	                SetFlag();
246	                cubeOp.Cube3Process(cube3AddrInfo[(taskId - 1) % 2],
247	                                    (__gm__ TYPE *)mm1WorkSpaceAddr,
248	                                    (__gm__ TYPE *)query,
249	                                    (__gm__ float *)dkWorkSpaceAddr);
250	                cubeOp.Cube3Process(cube3AddrInfo[(taskId - 1) % 2],
251	                                    (__gm__ TYPE *)mm2WorkSpaceAddr,
252	                                    (__gm__ TYPE *)dy,
253	                                    (__gm__ float *)dvWorkSpaceAddr);
254	                WaitFlag();
255	            }
256	        }
257	        if (cubeAddrInfo[taskId % 2].blockLength == 0) {
258	            running = false;
259	        }
260	        taskId++;
261	    }
262	    AscendC::CrossCoreSetFlag<2, PIPE_FIX>(CUBE2POST);
263	}
