265	template <typename TYPE, class TILING_CLASS>
266	__aicore__ inline void
267	FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::VectorProcess(GM_ADDR query,
268	                                                                       GM_ADDR key,
269	                                                                       GM_ADDR value,
270	                                                                       GM_ADDR dy,
271	                                                                       GM_ADDR atten_mask,
272	                                                                       GM_ADDR softmax_max,
273	                                                                       GM_ADDR softmax_sum,
274	                                                                       GM_ADDR attention_in,
275	                                                                       GM_ADDR actual_seq_qlen,
276	                                                                       GM_ADDR actual_seq_kvlen,
277	                                                                       GM_ADDR dq,
278	                                                                       GM_ADDR dk,
279	                                                                       GM_ADDR dv,
280	                                                                       GM_ADDR user,
281	                                                                       const TILING_CLASS *tilingData)
282	{
283	    VecPreProcess(dq, dk, dv, user, tilingData);
284	    VecSftgProcess(dy, attention_in, actual_seq_qlen, user, tilingData);
285	    VecMainProcess(atten_mask, softmax_max, softmax_sum, actual_seq_qlen, actual_seq_kvlen, user, tilingData);
286	    VecPostProcess(dq, dk, dv, user, tilingData);
287	}
