289	template <typename TYPE, class TILING_CLASS>
290	__aicore__ inline void FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::VecPreProcess(
291	    GM_ADDR dq, GM_ADDR dk, GM_ADDR dv, GM_ADDR user, const TILING_CLASS *tilingData)
292	{
293	    AscendC::TPipe pipePre;
294	    VectorInitOuput<TILING_CLASS> opPre;
295	    opPre.Init(&pipePre, dq, dk, dv, user, tilingData);
296	    opPre.Process();
297	    pipePre.Destroy();
