300	template <typename TYPE, class TILING_CLASS>
301	__aicore__ inline void FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::VecSftgProcess(
302	    GM_ADDR dy, GM_ADDR attention_in, GM_ADDR actual_seq_qlen, GM_ADDR user, const TILING_CLASS *tilingData)
303	{
304	    AscendC::TPipe pipeSoftmaxGrad;
305	    VectorSoftmaxGrad<TYPE, TILING_CLASS> opSoftmaxGrad;
306	    opSoftmaxGrad.Init(&pipeSoftmaxGrad, dy, attention_in, actual_seq_qlen, user, batch, tilingData);
307	    opSoftmaxGrad.Process();
308	    pipeSoftmaxGrad.Destroy();
309	    AscendC::SyncAll();
