312	template <typename TYPE, class TILING_CLASS>
313	__aicore__ inline void
314	FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::VecMainProcess(GM_ADDR atten_mask,
315	                                                                        GM_ADDR softmax_max,
316	                                                                        GM_ADDR softmax_sum,
317	                                                                        GM_ADDR actual_seq_qlen,
318	                                                                        GM_ADDR actual_seq_kvlen,
319	                                                                        GM_ADDR user,
320	                                                                        const TILING_CLASS *tilingData)
321	{
322	    AscendC::TPipe pipeVec;
323	    VecOp<TYPE, TILING_CLASS> op;
324	    struct VecAddrInfo vecAddrInfo;
325	    int32_t taskId = 0;
326	    bool running = true;
327	
328	    op.Init(softmax_max, softmax_sum, atten_mask, actual_seq_qlen, actual_seq_kvlen, user, tilingData, &pipeVec);
329	    VEC_ADDR::VecAddr vecAddr;
330	    vecAddr.init(batch, n1, g, headDim, GetBlockIdx(), actual_seq_qlen, actual_seq_kvlen, mixCoreNum, sparseMode);
331	    while (running) {
332	        vecAddr.addr_mapping(&vecAddrInfo);
333	        if (vecAddrInfo.blockLength > 0) {
334	            AscendC::WaitEvent(CUBE2VEC);
335	            vecAddrInfo.taskId = taskId;
336	            op.Process(vecAddrInfo);
337	            AscendC::CrossCoreSetFlag<2, PIPE_MTE3>(VEC2CUBE);
338	        }
339	        if (vecAddrInfo.blockLength == 0) {
340	            running = false;
341	        }
342	        taskId++;
343	    }
344	    pipeVec.Destroy();
345	    AscendC::WaitEvent(CUBE2POST);
346	    AscendC::SyncAll();
347	}
348	
