350	__aicore__ inline void FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::VecPostProcess(
351	    GM_ADDR dq, GM_ADDR dk, GM_ADDR dv, GM_ADDR user, const TILING_CLASS *tilingData)
352	{
