                                         GM_ADDR value,
                                         GM_ADDR dy,
                                         GM_ADDR atten_mask,
                                         GM_ADDR softmax_max,
                                         GM_ADDR softmax_sum,
                                         GM_ADDR attention_in,
                                         GM_ADDR actual_seq_qlen,
                                         GM_ADDR actual_seq_kvlen,
                                         GM_ADDR dq,
