template <typename TYPE, class TILING_CLASS>
__aicore__ inline void FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::Process(GM_ADDR query,
                                                                                        GM_ADDR key,
                                                                                        GM_ADDR value,
                                                                                        GM_ADDR dy,
                                                                                        GM_ADDR atten_mask,
                                                                                        GM_ADDR softmax_max,
                                                                                        GM_ADDR softmax_sum,
                                                                                        GM_ADDR attention_in,
                                                                                        GM_ADDR actual_seq_qlen,
                                                                                        GM_ADDR actual_seq_kvlen,
                                                                                        GM_ADDR dq,
                                                                                        GM_ADDR dk,
                                                                                        GM_ADDR dv,
                                                                                        GM_ADDR user,
                                                                                        const TILING_CLASS *tilingData)
{
    batch = tilingData->mlaTensorTilingData.b;
    n1 = tilingData->mlaTensorTilingData.n2 * tilingData->mlaTensorTilingData.g;
    n2 = tilingData->mlaTensorTilingData.n2;
    g = tilingData->mlaTensorTilingData.g;
    headDim = tilingData->mlaTensorTilingData.d;
    coreNum = tilingData->mlaTensorTilingData.coreNum;
    mixCoreNum = (coreNum + 1) / 2;
    sparseMode = tilingData->mlaTensorTilingData.sparseMode;
    mm1WorkSpaceAddr = user + tilingData->mlaTensorTilingData.mm1WorkspaceOffset;
    mm2WorkSpaceAddr = user + tilingData->mlaTensorTilingData.mm2WorkspaceOffset;
    dqWorkSpaceAddr = user + tilingData->mlaTensorTilingData.dqWorkSpaceOffset;
    dkWorkSpaceAddr = user + tilingData->mlaTensorTilingData.dkWorkSpaceOffset;
    dvWorkSpaceAddr = user + tilingData->mlaTensorTilingData.dvWorkSpaceOffset;

    if ASCEND_IS_AIC {
        CubeProcess(query,
                    key,
                    value,
                    dy,
                    atten_mask,
                    softmax_max,
                    softmax_sum,
                    attention_in,
                    actual_seq_qlen,
                    actual_seq_kvlen,
                    dq,
                    dk,
                    dv,
                    user,
                    tilingData);
    }

    if ASCEND_IS_AIV {
        VectorProcess(query,
                      key,
                      value,
                      dy,
                      atten_mask,
                      softmax_max,
                      softmax_sum,
                      attention_in,
                      actual_seq_qlen,
                      actual_seq_kvlen,
                      dq,
                      dk,
                      dv,
                      user,
                      tilingData);
    }
}

template <typename TYPE, class TILING_CLASS>
__aicore__ inline void
FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::CubeProcess(GM_ADDR query,
                                                                     GM_ADDR key,
                                                                     GM_ADDR value,
                                                                     GM_ADDR dy,
                                                                     GM_ADDR atten_mask,
                                                                     GM_ADDR softmax_max,
                                                                     GM_ADDR softmax_sum,
                                                                     GM_ADDR attention_in,
                                                                     GM_ADDR actual_seq_qlen,
                                                                     GM_ADDR actual_seq_kvlen,
                                                                     GM_ADDR dq,
                                                                     GM_ADDR dk,
                                                                     GM_ADDR dv,
                                                                     GM_ADDR user,
                                                                     const TILING_CLASS *tilingData)
{
    AscendC::TPipe pipeCube;
    CUBE_OP::CubeOp<TYPE> cubeOp;
    CUBE_ADDR::CubeAddr cubeAddr;
    struct CubeAddrInfo cubeAddrInfo[2];
    struct CubeAddrInfo cube3AddrInfo[2];
    int32_t taskId = 0;
    bool running = true;
    // cube2 and cube3 mix when headDim is 64 and sparseMode is 0
    bool cube23_mix_flag = (sparseMode == 0 && headDim == 64);

    cubeOp.Init(&pipeCube, n1, n2, headDim, sparseMode);
    cubeAddr.init(batch, n1, g, headDim, GetBlockIdx(), actual_seq_qlen, actual_seq_kvlen, mixCoreNum, sparseMode);

    while (running) {
        cubeAddrInfo[taskId % 2].taskId = taskId;
        cube3AddrInfo[taskId % 2].taskId = taskId;
        cubeAddr.addr_mapping(&cubeAddrInfo[taskId % 2], &cube3AddrInfo[taskId % 2]);
        if (cubeAddrInfo[taskId % 2].blockLength > 0) {
            SetFlag();
            cubeOp.Cube1Process(
                cubeAddrInfo[taskId % 2], (__gm__ TYPE *)query, (__gm__ TYPE *)key, (__gm__ float *)mm2WorkSpaceAddr);
            cubeOp.Cube1Process(
                cubeAddrInfo[taskId % 2], (__gm__ TYPE *)dy, (__gm__ TYPE *)value, (__gm__ float *)mm1WorkSpaceAddr);
            WaitFlag();
            AscendC::CrossCoreSetFlag<2, PIPE_FIX>(CUBE2VEC);
        }
        if (taskId > 0 && cubeAddrInfo[(taskId - 1) % 2].blockLength > 0) {
            if (cube23_mix_flag) {
                AscendC::WaitEvent(VEC2CUBE);
                SetFlag();
                cubeOp.Cube23Process(cubeAddrInfo[(taskId - 1) % 2],
                                     (__gm__ TYPE *)mm1WorkSpaceAddr,
                                     (__gm__ TYPE *)key,
                                     (__gm__ TYPE *)query,
                                     (__gm__ float *)dqWorkSpaceAddr,
                                     (__gm__ float *)dkWorkSpaceAddr);
                WaitFlag();
                SetFlag();
                cubeOp.Cube3Process(cube3AddrInfo[(taskId - 1) % 2],
                                    (__gm__ TYPE *)mm2WorkSpaceAddr,
                                    (__gm__ TYPE *)dy,
                                    (__gm__ float *)dvWorkSpaceAddr);
                WaitFlag();
            } else {
                SetFlag();
                cubeOp.Cube2Process(cubeAddrInfo[(taskId - 1) % 2],
                                    (__gm__ TYPE *)mm1WorkSpaceAddr,
                                    (__gm__ TYPE *)key,
                                    (__gm__ float *)dqWorkSpaceAddr);
                WaitFlag();
                SetFlag();
                cubeOp.Cube3Process(cube3AddrInfo[(taskId - 1) % 2],
                                    (__gm__ TYPE *)mm1WorkSpaceAddr,
                                    (__gm__ TYPE *)query,
                                    (__gm__ float *)dkWorkSpaceAddr);
                cubeOp.Cube3Process(cube3AddrInfo[(taskId - 1) % 2],
                                    (__gm__ TYPE *)mm2WorkSpaceAddr,
                                    (__gm__ TYPE *)dy,
                                    (__gm__ float *)dvWorkSpaceAddr);
                WaitFlag();
            }
        }
        if (cubeAddrInfo[taskId % 2].blockLength == 0) {
            running = false;
        }
        taskId++;
    }
    AscendC::CrossCoreSetFlag<2, PIPE_FIX>(CUBE2POST);
}

template <typename TYPE, class TILING_CLASS>
__aicore__ inline void
FlashAttentionScoreGradEnhanceBasic<TYPE, TILING_CLASS>::VectorProcess(GM_ADDR query,
                                                                       GM_ADDR key,
                                                                       GM_ADDR value,
                                                                       GM_ADDR dy,
                                                                       GM_ADDR atten_mask,
                                                                       GM_ADDR softmax_max,
                                                                       GM_ADDR softmax_sum,
